function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.report}"/></svg>`}
function brand(cls=''){return `<div class="brand ${cls}"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span><span class="wordmark">24일<span style="font-size:10px;font-weight:500;color:#8fa58d;margin-left:5px">투자게임</span></span></div>`}
const number=n=>Math.round(n||0).toLocaleString('ko-KR'), billions=n=>number(n)+'억', pct=n=>(n>0?'+':'')+Number(n||0).toFixed(1)+'%', sectorColors={'기술':['#e8f1e9','#628b67'],'항공':['#ebf0f6','#758fad'],'식품':['#f7f0e2','#b39966'],'의료·제약':['#f1ecf5','#9983ad'],'미래사업':['#e8f2f1','#6b9b92']};
let noteDraft={thesis:'',risk:'',horizon:'다음 실적 발표까지'},tradeDrafts={};
let newsHorizon='all',newsAdvanced=false,companyTab='chart',noteComposerOpen=false,journalFilter='all',adminBusy=false;

let earningsQ=null,earningsAsset='HBEL',newsMode='all',newsFocus='',marketSearch='',marketSector='전체',journalAsset='HBEL',evidenceDraft=null,refreshing=false,activeArticle=null;
const baseBank=legacyViews.bank,basePortfolio=legacyViews.portfolio;
async function api(url,opt={}){if(S?.demo){if(url.startsWith('/history/'))return S.histories[url.split('/').pop()]||[];if(opt.method&&opt.method!=='GET')throw Error('읽기 전용 체험입니다. 게임방에 참가하면 거래와 기록을 할 수 있어요.')}return legacyViews.api(url,opt)}
async function startDemo(){try{S=await legacyViews.api('/demo');tab='home';render();window.scrollTo(0,0)}catch(e){toast(e.message)}}
function exitDemo(){S=null;tab='home';render()}
function companyAvatar(a){let c=sectorColors[a?.sector]||['#edf2ea','#7a9170'];return `<span class="company-avatar" style="--tile:${c[0]};--tile-ink:${c[1]}">${esc(a?.name?.slice(0,1)||'H')}</span>`}
function latestReport(id,q=null){return (S.reports||[]).find(r=>r.asset===id&&(q===null||r.quarter===q))}
function forecastFor(id,q){return (S.forecasts||[]).find(r=>r.asset===id&&r.quarter===q)}
function reportBadge(r){let v=r?.market_verdict||r?.verdict;return `<span class="verdict ${v==='예상 상회'?'beat':v==='예상 하회'?'miss':''}">${esc(v||'발표 대기')}</span>`}
function currentView(){return S?.role==='admin'&&tab==='preview'?previewTab:tab}
function isPreview(){return S?.role==='admin'&&tab==='preview'}
function myData(){return isPreview()&&previewData?previewData:S}
function emptyState(text){return `<div class="empty">${esc(text)}</div>`}
function smallLink(label,action){return `<button class="text-btn" onclick="${action}">${label} ${icon('chevron')}</button>`}

function authView(){
 let modes=[['join','학생 참가'],['admin','교사 로그인'],['create','방 만들기']];
 return `<div class="auth-shell"><section class="auth-hero">${brand()}<div class="eyebrow">CLASSROOM INVESTMENT LAB</div><h1>뉴스를 읽고,<br>기업의 내일에<br><em>투자하다.</em></h1><p>뉴스 속 단서를 찾고, 분기 실적으로 확인하는 투자.<br>오늘의 선택이 내일의 배움이 되는 우리 반 금융시장.</p><div class="auth-pills"><span>가상의 1년, 24일</span><span>20개 가상 기업</span><span>4번의 분기 실적</span></div><div class="preview-finance" aria-label="기업 실적을 비교하는 화면 예시"><div class="preview-head"><div class="preview-company"><span class="company-avatar">한</span><div>한빛전자<div class="sub">기업 분석 리포트 · 화면 예시</div></div></div><span class="certainty fact">실적 비교</span></div><h3>기대를 숫자로 확인해요.</h3><span class="sub">뉴스 → 투자 가설 → 실적 발표 → 돌아보기</span><div class="preview-bars">${[[27,36],[36,46],[42,59],[48,73]].map(([a,b])=>`<div><i style="height:${a}px"></i><i style="height:${b}px"></i></div>`).join('')}</div><div class="preview-legend"><span><i></i>시장 예상</span><span><i class="actual"></i>발표 실적</span></div></div><div class="auth-footer">24 DAYS — READ THE NEWS, MAKE YOUR CHOICE.</div></section><section class="auth-form-wrap"><div class="auth-form">${brand('auth-mobile-title')}<div class="eyebrow">WELCOME TO YOUR CLASSROOM</div><h2>${authMode==='create'?'우리 반 시장을 열어요.':authMode==='admin'?'수업을 이어가 볼까요?':'오늘의 투자를 시작해요.'}</h2><p class="sub">${authMode==='create'?'교사만의 비밀번호로 새 게임방을 만드세요.':authMode==='admin'?'게임방 코드와 교사용 비밀번호를 입력하세요.':'게임방 코드와 이름, 개인 PIN으로 입장하세요.'}</p><div class="seg">${modes.map(([k,v])=>`<button type="button" class="${authMode===k?'active':''}" onclick="authMode='${k}';render()">${v}</button>`).join('')}</div><form onsubmit="event.preventDefault();submitAuth()">${authMode==='create'?`<label for="roomName">게임방 이름</label><input class="input" id="roomName" maxlength="50" value="우리 반 투자 연구소" required><label for="pw">교사용 비밀번호</label><input class="input" id="pw" type="password" minlength="4" autocomplete="new-password" placeholder="4자 이상 입력" required><label for="startCash">학생 시작 자금</label><input class="input" id="startCash" type="number" value="100000" min="1000" max="100000000" required>`:`<label for="code">게임방 코드</label><input class="input" id="code" maxlength="6" value="${esc(joinCode)}" placeholder="6자리 게임방 코드" style="text-transform:uppercase;letter-spacing:2px" autocomplete="off" required>${authMode==='join'?`<label for="nickname">이름 또는 별명</label><input class="input" id="nickname" maxlength="24" placeholder="수업에서 사용하는 이름" autocomplete="username" required><label for="pin">개인 PIN</label><input class="input" id="pin" type="password" minlength="4" placeholder="기억할 PIN, 4자 이상" autocomplete="current-password" required>`:`<label for="pw">교사용 비밀번호</label><input class="input" id="pw" type="password" minlength="4" autocomplete="current-password" placeholder="교사용 비밀번호" required>`}`}<button type="submit" class="btn submit">${authMode==='create'?'게임방 만들기':authMode==='admin'?'교사 운영센터 입장':'투자 연구소 입장'} ${icon('arrow')}</button></form><button type="button" class="btn secondary" style="width:100%;margin-top:10px" onclick="startDemo()">${icon('eye')} 학생 화면 미리 체험하기</button><p class="auth-hint">${authMode==='join'?'처음 참가하면 계정이 만들어져요.<br>다시 접속할 때도 같은 이름과 PIN을 사용하세요.':'학생은 QR 코드와 게임방 코드로 쉽게 참가할 수 있어요.'}</p><div class="auth-small">${icon('shield')} 실제 돈을 사용하지 않는 교육용 가상 금융시장</div></div></section></div>`
}

const studentMenu=[['home','오늘의 소식','news'],['market','투자하기','market'],['portfolio','내 자산','portfolio'],['journal','투자 기록','journal']];
const teacherMenu=[['home','수업 진행','home'],['market','시장 보기','market'],['players','학생 현황','people'],['admin','운영 설정','settings']];
function head(){
 let adminMode=S.role==='admin',r=S.room,menu=adminMode?teacherMenu:studentMenu;
 let names={home:adminMode?'수업 진행':'오늘의 소식',news:'뉴스 모아보기',earnings:'분기 실적',market:adminMode?'시장 보기':'투자하기',portfolio:'내 자산',journal:'투자 기록',bank:adminMode?'시장 보기 · 예금':'투자하기 · 예금',orders:adminMode?'거래와 투자 근거':'입출금 내역',preview:'학생 화면 미리보기',players:'학생 현황',admin:'운영 설정',detail:asset(selected)?.name||'기업 분석'};
 let subtitles={home:adminMode?'숫자보다 먼저, 학생들의 판단 과정을 살펴보세요.':'뉴스를 읽고, 기업을 살피고, 나만의 판단을 기록해 보세요.',news:'새로운 소식과 이미 확인된 사실을 구분해 읽어 보세요.',earnings:'기대했던 이야기가 실제 매출과 이익으로 이어졌을까요?',market:'주가의 움직임 뒤에 있는 기업과 산업을 살펴보세요.',portfolio:'오늘의 선택이 모여 만든 나의 자산입니다.',journal:'어떤 근거로 판단했는지, 무엇을 배웠는지 남겨 보세요.',players:'기사 열람, 근거 있는 거래, 투자 노트와 돌아보기 현황입니다.'};
 let next=(S.calendar||[]).find(q=>!q.released&&q.day>=r.day),finished=r.phase==='finished';
 if(finished){names.home='24일 결산';subtitles.home='우리 반의 투자 결과와 각자의 투자 스타일을 함께 돌아보세요.';}
 return `<aside class="side">${brand()}<div class="side-label">${adminMode?'교사 운영':'우리 반 투자 연구소'}</div><nav class="side-nav" aria-label="주 메뉴">${menu.map(([k,v,i])=>`<button class="${navGroup(tab,adminMode)===k?'active':''}" onclick="${adminMode?`goTeacher('${k}')`:`go('${k}')`}" ${navGroup(tab,adminMode)===k?'aria-current="page"':''}>${icon(i)}<span class="nav-text">${finished&&k==='home'?'24일 결산':v}</span>${k==='earnings'&&S.calendar?.some(q=>q.released&&q.day===r.day)?'<span class="nav-badge">NEW</span>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="room-mini"><div class="sub">${esc(r.name)}</div><div class="room-code">${esc(r.code)}</div><div class="sub">24일 동안 경험하는 가상의 1년</div></div><div class="side-user"><div class="avatar">${adminMode?'T':esc(S.player.name.slice(0,1))}</div><div><b>${adminMode?'선생님':esc(S.player.name)}</b><div class="sub">${adminMode?'교사':'학생'} 계정</div></div><button class="logout" aria-label="로그아웃" onclick="logout()">${icon('logout')}</button></div></div></aside><div class="workspace"><div class="topbar"><div class="crumb">우리 반 투자 연구소 ${icon('chevron')} <strong>${esc(names[tab]||'기업 분석')}</strong></div>${brand('mobile-brand')}<div class="top-meta">${rankingChip()}<span class="sub">${esc(r.name)}</span>${adminMode?`<button class="btn secondary sm preview-toggle" onclick="openStudentView()">${icon('eye')} 학생 화면 보기</button>`:''}<span class="live"><i></i>${finished?'결산 완료':r.phase==='trading'?'거래 중':'장 마감'}</span><button class="text-btn" title="새로고침" aria-label="새로고침" onclick="refresh()">${icon('refresh')}</button><button class="logout mobile-brand" aria-label="로그아웃" onclick="logout()">${icon('logout')}</button></div></div><div id="classroom-clock">${classClock()}</div><main class="content"><div class="page-title"><div><h1>${esc(names[tab]||'기업 분석')}</h1><p class="sub">${subtitles[tab]||'정보를 비교하고 투자 이유를 생각해 보세요.'}</p></div><div class="title-meta"><div class="eyebrow">가상의 1년 · ${Math.round(r.day/24*100)}%</div><div class="period">${Math.ceil(r.day/6)}분기 <span style="color:#aec0ab;padding:0 5px">/</span> ${r.day}일차</div>${next?`<span class="sub" style="font-size:12px">다음 실적 ${next.day}일차</span>`:''}</div></div>${S.demo?'<div class="notice" style="margin-bottom:16px">6일차 학생 화면을 보여 주는 읽기 전용 체험입니다. 직접 거래하려면 게임방에 참가해 주세요. <button class="text-btn" onclick="exitDemo()">입장 화면으로 →</button></div>':adminMode?'':dayFinishPanel()}<div id="page"></div></main></div>`;
}
function rankingChip(){
 const data=isPreview()?previewData:S,r=data?.ranking;if(!r)return '';
 return `<span class="ranking-chip" title="투자 수익률 기준 · 수수료와 받을 채권 이자 반영 · 교사 현금 조정 제외 · 동률은 공동 순위">${isPreview()?'학생 순위':'내 순위'} <b>${r.tied?'공동 ':''}${r.rank}위</b><small>/ ${r.total}명</small></span>`;
}
function dayFinishPanel(){
 const ready=S.player?.day_ready,finished=S.room.phase==='finished',readOnly=S.role!=='player'||S.demo;
 return `<div class="daily-done ${ready?'done':''}"><div><b>${finished?'24일의 투자가 끝났어요.':ready?'오늘 선택 완료를 알렸어요.':'오늘의 선택을 마쳤나요?'}</b><span class="sub">${finished?'기록을 보며 나의 판단을 돌아보세요.':ready?'다시 거래하면 선택 중으로 바뀌어요.':'기다리기로 했다면 거래 없이 완료해도 괜찮아요.'}</span></div>${S.room.phase==='trading'?`<button class="btn ${ready?'ghost':'secondary'} sm" ${readOnly?'disabled':''} onclick="setReady(${!ready})">${icon(ready?'refresh':'check')}${ready?'완료 표시 취소':'오늘 선택 완료'}</button>`:finished&&S.finale&&currentView()!=='home'?'<button class="btn secondary sm" onclick="go(\'home\')">최종 결산 보기</button>':`<span class="tag">${finished?'최종 결산':'수업 잠시 멈춤'}</span>`}</div>${S.room.day===24&&!finished?'<p class="final-day-notice">오늘이 마지막 투자일이에요. 마감하면 주식·ETF·채권·금을 현재 시세로 자동 매도해요. 매도 수수료와 마지막 채권 이자까지 최종 금액에 반영돼요.</p>':''}`;
}
async function setReady(ready){try{await api('/day/'+(ready?'complete':'reopen'),{method:'POST'});toast(ready?'오늘 선택 완료를 선생님께 알렸어요.':'다시 선택할 수 있어요.');await refresh()}catch(e){toast(e.message)}}
function go(k){closeModal();if(isPreview()&&['home','market','detail','bank','portfolio','orders','news','earnings','journal'].includes(k)){previewTab=k}else{tab=k}render();window.scrollTo({top:0,behavior:'smooth'})}
function stat(label,value,foot,featured=false,ic='wallet'){return `<div class="stat ${featured?'featured':''}"><div class="stat-label">${icon(ic)}${label}</div><strong>${value}</strong><div class="stat-foot">${foot}</div>${featured?`<span class="micro">${icon('market')}</span>`:''}</div>`}
function calendarCards(){return `<div class="earn-date">${(S.calendar||[]).map(q=>`<div class="${q.released?'done':q.day>=S.room.day&&q.day===((S.calendar||[]).find(x=>!x.released&&x.day>=S.room.day)||{}).day?'current':''}"><span>QUARTER ${q.quarter}</span><b>${q.day}일차</b><small>${q.released?'✓ 실적 공개':q.day<S.room.day?'기록 없음':q.day===S.room.day?'오늘 발표':'발표 예정'}</small></div>`).join('')}</div>`}
function sectorBoard(){return `<div class="sector-grid">${['TECH','AIR','FOOD','HEAL','FUTR'].map(id=>{let a=asset(id);return `<button class="sector-mini" onclick="marketSector='${esc(a.sector)}';marketFilter='stock';go('market')"><span>${esc(a.sector)}</span><b class="${a.change>=0?'up':'down'}">${pct(a.change)}</b><div class="sector-line ${a.change<0?'negative':''}"><i style="width:${Math.min(100,25+Math.abs(a.change)*10)}%"></i></div></button>`}).join('')}</div>`}
function focusRow(a){return `<div class="focus-row" role="button" tabindex="0" onclick="detail('${a.id}')" onkeydown="if(event.key==='Enter')detail('${a.id}')">${companyAvatar(a)}<div class="desc"><b>${esc(a.name)}</b><p>${esc(a.sector)} · ${risk[a.risk]}</p></div><div class="right"><b>${money(a.price)}</b><div class="sub ${a.change>=0?'up':'down'}">${pct(a.change)}</div></div></div>`}
function playerHome(){
 if(S.room.phase==='finished'&&S.finale)return finaleView();
 const p=S.player,today=S.news.filter(n=>n.day===S.room.day),released=(S.calendar||[]).find(q=>q.released&&q.day===S.room.day),next=(S.calendar||[]).find(q=>!q.released&&q.day>S.room.day);
 const watch=[...new Set([...(S.watchlist||[]),...(S.holdings||[]).map(h=>h.asset)])].map(asset).filter(Boolean);
 return `<div class="wealth-strip"><span>내 총자산 <strong>${money(p.net)}</strong></span><span>사용 가능 <b>${money(p.cash)}</b></span><span>수익률 <b class="${p.profit>=0?'up':'down'}">${pct(p.profit/S.room.start_cash*100)}</b></span>${smallLink('내 자산',"go('portfolio')")}</div>
 ${released?`<div class="report-announcement"><div>${icon('report')}<div><b>${released.quarter}분기 실적이 나왔어요.</b><p>뉴스로 바뀐 기대와 실제 이익을 비교해 보세요.</p></div></div><button class="btn dark sm" onclick="go('earnings')">실적 비교하기 ${icon('arrow')}</button></div>`:''}
 <div class="today-layout"><section class="card today-news"><div class="section-title"><div><h2>오늘 먼저 읽을 소식</h2><p class="sub no-margin">새로운 전망인지, 확인된 결과인지 살펴보세요.</p></div>${smallLink('모든 뉴스',"go('news')")}</div>${digestCards(today)}</section>
 <aside class="stack"><div class="card"><div class="section-title"><h2>내가 살펴보는 기업</h2>${smallLink('투자하기',"go('market')")}</div>${watch.length?watch.slice(0,4).map(focusRow).join(''):emptyState('기업 화면의 ☆를 누르면 관심 목록에 담을 수 있어요.')}<p class="hint no-margin">${next?`다음 실적 발표는 ${next.day}일차예요.`:'공개된 실적에서 내 판단을 확인해 보세요.'}</p></div>${npcPanel(true)}<div class="card compact-prompt"><b>오늘은 기다려도 괜찮아요.</b><p class="sub">거래하지 않은 이유도 투자 기록에 남길 수 있어요.</p><button class="text-btn" onclick="openNoteComposer()">생각 남기기 ${icon('arrow')}</button></div></aside></div>`;
}
function horizonTag(n){if(!['company','followup'].includes(n.kind))return '';let labels={short:'단기',next_quarter:'다음 분기',year_end:'연말'},k=n.horizon||'short';return `<span class="horizon-tag ${k}">${labels[k]||'단기'} 영향</span>`}
function horizonDetails(n){if(!['company','followup'].includes(n.kind))return '';let labels={short:'단기 운영',next_quarter:'다음 분기 사업',year_end:'연말 사업'},k=n.horizon||'short';return `<div class="horizon-detail"><div class="flex"><b>${icon('calendar')} ${labels[k]||'단기 운영'} 소식</b>${horizonTag(n)}</div><p>${n.expected_start?`실적 영향 예상 기간: <b>${n.expected_start}~${n.expected_end||n.expected_start}일차</b><br>`:''}기사에 대한 기대와 실적에 반영되는 시점은 달라요. 일정은 바뀔 수 있고 사업이 예상과 다르게 진행될 수 있어요.${k!=='short'?'<br>준비·연구 비용이 먼저 발생해 초기 이익이 줄 수도 있어요.':''}</p></div>`}
function filterHorizon(k){newsHorizon=k;if(k==='next_quarter'||k==='year_end')newsScope='all';render()}
function projectBoard(aid=null){
 let my=new Set([...(S.watchlist||[]),...(S.holdings||[]).map(h=>h.asset)]);
 let list=(S.events||[]).filter(e=>e.horizon&&e.horizon!=='short'&&e.expected_end>=S.room.day&&(!aid||e.asset===aid)&&(!newsFocus||e.asset===newsFocus)&&(newsSector==='전체'||asset(e.asset)?.sector===newsSector)&&(newsMode!=='mine'||my.has(e.asset))&&(newsHorizon==='all'||newsHorizon===e.horizon)).sort((a,b)=>a.expected_start-b.expected_start||a.start_day-b.start_day).slice(0,aid?3:6);
 if(!list.length)return '';
 return `<div class="project-board"><div class="section-title"><h2>${aid?'이 기업의 장기 사업':'기억해 둘 장기 뉴스'}</h2><span class="sub">예상 기간 · 확정 수익 아님</span></div><div class="project-grid">${list.map(e=>{let first=S.news.filter(n=>n.event_id===e.id).sort((a,b)=>a.day-b.day||a.id-b.id)[0],done=['confirmed','reversed'].includes(e.stage),label=e.stage==='delayed'?'일정 조정':e.stage==='reversed'?'예상과 다른 결과':done?'영업 영향 중':'진행 확인 중';return `<div class="project-item"><div class="flex"><span class="horizon-tag ${e.horizon}">${e.horizon==='year_end'?'연말':'다음 분기'}</span><span class="sub">${label}</span></div><b>${esc(asset(e.asset)?.name)} · ${esc(e.title)}</b><p>${e.start_day}일차 첫 보도 → ${e.expected_start}~${e.expected_end}일차 영향 예상</p>${first?`<button class="text-btn" onclick="openArticle(${first.id})">처음 기사 다시 읽기 ${icon('arrow')}</button>`:''}</div>`}).join('')}</div></div>`
}
function benchmarkCard(){if(!S.player)return '';let rate=S.benchmark?.deposit_rate??.1,progress=S.benchmark?.progress_rate??rate*(S.room.day-1)/23,own=S.player.profit/S.room.start_cash,diff=(own-progress)*100;return `<div class="card benchmark-card"><div class="section-title"><h2>24일 예금 10%와 나의 투자</h2><span class="sub">같은 시작 자금 기준</span></div><div class="benchmark-grid"><div><span>예금 만기 수익률</span><strong>+${(rate*100).toFixed(1)}%</strong><small>${money(S.room.start_cash)} → ${money(S.room.start_cash*(1+rate))}</small></div><div><span>오늘 진행률의 예금 비교선</span><strong>${pct(progress*100)}</strong><small>${S.room.day}일차 · 만기까지의 기간으로 나눈 값</small></div><div><span>나의 투자 수익률</span><strong class="${own>=0?'up':'down'}">${pct(own*100)}</strong><small>오늘 비교선보다 ${Math.abs(diff).toFixed(1)}%p ${diff>=0?'높아요':'낮아요'}</small></div></div><p class="hint no-margin" style="margin-top:15px">비교선은 예금 10%를 게임 진행률에 맞춰 나눈 참고선이며, 실제 예금 이자는 만기에 지급됩니다. 투자 수익은 현금·보유 상품·예금·받을 채권 이자를 합쳐 계산하고 교사의 현금 지급·차감은 제외해요.</p></div>`}
function portfolio(){return bondIncomePanel()+`<div class="portfolio-costs"><span>지금까지 낸 수수료 <b>${money(S.player.fees_paid||0)}</b></span><span class="sub">수익률에는 이미 낸 수수료가 반영돼요.</span></div>`+basePortfolio()+`<details class="disclosure"><summary>24일 예금 10%와 수익률 비교하기</summary>${benchmarkCard()}</details>`}
function breakingBanner(){
 const n=(S.news||[]).find(n=>n.is_breaking&&n.day===S.room.day);if(!n)return '';
 const a=asset(n.sector);
 return `<section class="breaking-banner" role="status" aria-label="오늘의 속보"><span class="breaking-label">속보</span><div><button class="breaking-title" onclick="openArticle(${n.id})">${esc(newsTitle(n))}</button><p>${esc(a?.name||n.sector)} 오늘 ${pct(a?.change||0)} · 현재 가격에 반영됐어요.</p></div><button class="text-btn" onclick="openArticle(${n.id})">기사 보기 ${icon('arrow')}</button></section>`;
}
function certaintyTag(n){if(n.is_breaking)return '<span class="certainty breaking">속보 · 사실 확인</span>';let fact=n.certainty?.includes('확인')||n.certainty?.includes('현황');return `<span class="certainty ${n.kind==='earnings'?'earn':fact?'fact':''}">${esc(n.certainty||'보도')}</span>`}
function newsCards(arr,compact=false,contextAsset=null){return arr.map(n=>{let read=(S.read_ids||[]).includes(n.id),rel=(n.related_assets||[]).map(id=>asset(id)).filter(Boolean);let target=asset(n.sector);return `<article class="article-card ${n.is_breaking?'breaking-article':''} ${compact?'compact':''}" tabindex="0" role="button" onclick="openArticle(${n.id})" onkeydown="if(event.key==='Enter')openArticle(${n.id})"><div class="article-meta"><div class="article-source"><i></i>${esc(n.source||'하루경제')}<span>· ${n.day}일차</span></div>${certaintyTag(n)}</div><h3>${esc(newsTitle(n))}</h3><p class="news-preview">${esc(articleSummary(n))}</p>${etfNewsBadge(n,contextAsset)}<div class="article-footer">${rel.slice(0,2).map(a=>`<button onclick="event.stopPropagation();detail('${a.id}')">${esc(a.name)}</button>`).join('')}${!rel.length?`<span>${target?esc(target.name):esc(n.sector)}</span>`:''}${horizonTag(n)}${n.kind==='followup'?'<span>후속 보도</span>':''}<span style="margin-left:auto" class="${read?'read-tick':''}">${read?'✓ 열람함':'기사 읽기 ↗'}</span></div></article>`}).join('')||emptyState('이 조건에 해당하는 기사가 아직 없어요.')}
function news(){
 const my=new Set([...(S.watchlist||[]),...(S.holdings||[]).map(h=>h.asset)]),from=(Math.ceil(S.room.day/6)-1)*6+1;
 const source=asset(newsFocus)?.type==='etf'?relatedAssetNews(asset(newsFocus),null):S.news;
 const items=source.filter(n=>(newsHorizon==='all'||n.horizon===newsHorizon)&&(newsScope==='all'||(newsScope==='today'?n.day===S.room.day:n.day>=from))&&(newsSector==='전체'||n.sector===newsSector||asset(n.sector)?.sector===newsSector||(n.related_assets||[]).some(id=>asset(id)?.sector===newsSector))&&(newsMode!=='mine'||[...my].some(id=>newsMatchesAsset(n,asset(id))))&&(newsMode!=='followup'||n.kind==='followup')&&(!newsFocus||newsMatchesAsset(n,asset(newsFocus))));
 const advancedOn=newsSector!=='전체'||newsHorizon!=='all'||newsMode==='followup'||!!newsFocus;
 return `<div class="filter-bar news-primary-filters"><div class="seg" aria-label="뉴스 기간">${[['today','오늘'],['quarter','이번 분기'],['all','전체 기간']].map(([k,v])=>`<button class="${newsScope===k?'active':''}" onclick="newsScope='${k}';render()">${v}</button>`).join('')}</div><div class="filter-left"><button class="chip ${newsMode==='mine'?'active':''}" aria-pressed="${newsMode==='mine'}" onclick="newsMode=newsMode==='mine'?'all':'mine';render()">관심·보유 기업</button><button class="text-btn" aria-expanded="${newsAdvanced}" onclick="newsAdvanced=!newsAdvanced;render()">상세 필터${advancedOn?' · 적용 중':''} ${newsAdvanced?'접기':'열기'}</button></div></div>
 ${newsAdvanced?`<div class="advanced-filters"><div><label for="news-sector">산업</label><select id="news-sector" class="input" onchange="newsSector=this.value;render()">${['전체','기술','항공','식품','의료·제약','미래사업'].map(k=>`<option ${newsSector===k?'selected':''}>${k}</option>`).join('')}</select></div><div><label for="news-horizon">실적 영향 예상 시점</label><select id="news-horizon" class="input" onchange="filterHorizon(this.value)">${[['all','모든 시점'],['short','단기'],['next_quarter','다음 분기'],['year_end','연말']].map(([k,v])=>`<option value="${k}" ${newsHorizon===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="filter-left"><button class="chip ${newsMode==='followup'?'active':''}" onclick="newsMode=newsMode==='followup'?'all':'followup';render()">후속 보도만</button><button class="text-btn" onclick="resetNewsFilters()">필터 초기화</button></div></div>`:''}
 ${newsFocus?`<button class="chip active" onclick="newsFocus='';render()">${esc(asset(newsFocus)?.name||newsFocus)} ×</button>`:''}
 <div class="news-layout-switch">${[['digest','핵심 5건'],['stories','사건별'],['all','전체 기사']].map(([k,v])=>`<button class="chip ${newsLayout===k?'active':''}" onclick="newsLayout='${k}';render()">${v}</button>`).join('')}<span class="sub">조건에 맞는 기사 ${items.length}건</span></div>
 ${newsLayout==='digest'?digestCards(items):newsLayout==='stories'?storyCards(items):`<div class="news-grid">${newsCards(items,false,asset(newsFocus))}</div>`}
 ${newsPricingHelp()}<div class="news-footer">${npcPanel(true)}<p class="hint">뉴스는 교육용 가상 기사예요. 기대는 단기 가격에, 실제 사업 성과는 기사에 적힌 기간의 실적에 영향을 줍니다.</p></div>`;
}
function closeModal(){let el=$('#modal-root');if(el)el.innerHTML='';activeArticle=null;document.body.style.overflow=''}
function showModal(html,label='기사와 투자 정보'){$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(label)}">${html}</section></div>`;document.body.style.overflow='hidden';$('#modal-root .modal-x')?.focus()}
function articleExtra(n){
 const metrics=metricsPanel(n),timing=horizonDetails(n);
 if(!metrics&&!timing&&!n.lens)return '';
 return `<details class="disclosure article-extra"><summary>숫자·일정 자세히 보기</summary>${metrics}${timing}${n.lens?`<p class="hint">${esc(n.lens)}</p>`:''}${n.reading&&n.reading.body!==n.body?`<details class="disclosure article-original"><summary>원문 보기</summary><p>${esc(n.body)}</p></details>`:''}</details>`;
}
function newsPricingHelp(){return `<details class="disclosure news-pricing-help"><summary>뉴스는 주가에 어떻게 반영되나요?</summary><p>기사의 매출·이익 변화와 사업 기간을 보고 회사에 대한 기대가 얼마나 달라졌는지 계산해요. 같은 소식이 반복됐다고 주가 효과를 또 더하지는 않아요.</p><p>새 뉴스의 가격 영향은 다음 날 60%, 그다음 날 25%, 셋째 날 15%로 나눠요. 다른 뉴스·시장 흐름·회사별 변동도 더해지므로 실제 주가는 기사와 다른 방향으로 움직일 수 있어요.</p><p>분기 실적 발표는 발표 직전의 기대보다 실제 이익이 얼마나 높거나 낮은지 비교하고, 발표 당일 가격에 반영해요. 매출 10% 증가는 주가 10% 상승을 뜻하지 않아요.</p></details>`}
async function openArticle(id){
 let n=S.news.find(n=>n.id===id);if(!n)return toast('기사를 찾을 수 없어요.');let context=currentEtfNewsContext(n),rel=(n.related_assets||[]).map(asset).filter(Boolean),related=S.news.filter(x=>x.event_id&&x.event_id===n.event_id).sort((a,b)=>a.day-b.day||a.id-b.id);
 showModal(`<div class="modal-titlebar"><div class="article-source sub">${esc(n.source||'하루경제')} · ${n.day}일차 ${certaintyTag(n)}</div><button class="modal-x" aria-label="닫기" onclick="closeModal()">${icon('close')}</button></div><h2>${esc(newsTitle(n))}</h2>${context?etfNewsBadge(n,context):''}<div class="article-body easy-article">${readingParagraphs(n)}</div>${articleExtra(n)}${related.length>1?`<details class="disclosure article-history"><summary>처음 기사와 이어진 소식 ${related.length}건 보기</summary><div class="trail" style="margin-top:16px">${related.map(x=>`<div class="trail-item"><small>${x.day}일차 · ${esc(x.certainty)}</small><b>${esc(newsTitle(x))}</b>${x.id!==n.id?`<button class="text-btn" onclick="openArticle(${x.id})">이 기사 읽기 →</button>`:''}</div>`).join('')}</div></details>`:''}${storyReports(related.length?related:[n])}<div class="modal-actions">${rel.slice(0,3).map(a=>`<button class="btn secondary sm" onclick="analyzeArticle(${n.id},'${a.id}')">${esc(a.name)} 분석</button>`).join('')}${S.role==='player'?`<button class="btn dark sm" onclick="noteFromNews(${n.id}${context?`,'${context.id}'`:''})">${icon('journal')} ${context?esc(context.name)+'로 생각 남기기':'이 기사로 생각 남기기'}</button>`:''}${n.kind==='earnings'?`<button class="btn dark sm" onclick="go('earnings')">실적센터 보기</button>`:''}</div>`);
 activeArticle=id;
 if(S.role==='player'&&!S.demo&&!(S.read_ids||[]).includes(id)){try{await api('/news/'+id+'/read',{method:'POST'});S.read_ids=[...(S.read_ids||[]),id];if(S.learning)S.learning.read_count=S.read_ids.length}catch(e){toast(e.message)}}
}
function noteFromNews(id,aid=null){const n=S.news.find(x=>x.id===id);journalAsset=aid||(n?.related_assets||[])[0]||'HBEL';evidenceDraft=id;noteComposerOpen=true;closeModal();go('journal')}
function financialTiles(r){
 const tiles=rows=>rows.map(([k,v,h])=>`<div class="financial-tile"><span>${k}</span><strong>${v}</strong><small>${h}</small></div>`).join('');
 return `<div class="financial-grid main-financials">${tiles([
 ['매출',billions(r.revenue),r.quarter?`이전 분기 대비 ${pct(r.revenue_growth)}`:'제품·서비스를 팔아 번 금액'],
 ['영업이익',billions(r.profit),r.quarter?`이전 분기 대비 ${pct(r.profit_growth)}`:'사업 비용을 빼고 남은 금액'],
 ['기대와 비교',r.quarter?reportBadge(r):'발표 전',r.quarter?'발표 직전 시장 기대 기준':'첫 실적 발표에서 확인해요']])}</div>
 <details class="disclosure"><summary>이익률·현금·부채 자세히 보기</summary><div class="financial-grid">${tiles([
 ['영업이익률',Number(r.margin).toFixed(1)+'%','매출 100원 중 남은 영업이익'],['보유 현금',billions(r.cash),'회사가 보유한 현금'],['부채',billions(r.debt),'회사가 갚아야 할 자금']])}</div></details>`;
}
function expectationsChart(r){let market=r.market_expected_profit??r.expected_profit,rows=[['당초 예상',r.expected_profit,''],['발표 직전 기대',market,'market'],['실제 발표',r.profit,'actual']],m=Math.max(...rows.map(x=>Math.abs(x[1])),1);return `<div class="compare-chart"><div class="section-title"><b style="font-size:12px">당초 예상 → 바뀐 기대 → 실제 결과</b>${reportBadge(r)}</div>${rows.map(([k,v,cls])=>`<div class="compare-line"><span>${k}</span><div class="compare-track"><div class="compare-fill ${cls}" style="width:${Math.abs(v)/m*100}%${v<0?';background:#b8958b':''}"></div></div><b>${billions(v)}</b></div>`).join('')}<p class="hint">당초 예상은 그대로 보관해요. 발표 직전 기대에는 공개된 사업 목표·준비 비용·일정·결과가 반영돼요. 가격은 이 기대와 실제 결과의 차이에도 반응해요.${rows.some(x=>x[1]<0)?' 막대 길이는 금액의 절댓값이며 음수는 손실이에요.':''}</p></div>`}
function reportTrend(id){let rr=(S.reports||[]).filter(r=>r.asset===id).sort((a,b)=>a.quarter-b.quarter);if(rr.length<2)return '<p class="hint">첫 분기 실적이 나오면 변화 추이가 표시됩니다.</p>';let W=600,H=165,l=45,t=22,b=30,w=520,vs=rr.flatMap(r=>[r.profit,r.expected_profit]),lo=Math.min(0,...vs),hi=Math.max(1,...vs),y=v=>t+(hi-v)/Math.max(1,hi-lo)*(H-t-b),step=w/rr.length;return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;max-height:190px" role="img" aria-label="분기별 실제 영업이익과 사전 예상 영업이익 비교"><line x1="${l}" x2="${l+w}" y1="${y(0)}" y2="${y(0)}" stroke="#dbe5d3"/>${rr.map((r,i)=>{let x=l+step*i+step/2;return `<rect x="${x-20}" y="${Math.min(y(0),y(r.expected_profit))}" width="16" height="${Math.max(1,Math.abs(y(0)-y(r.expected_profit)))}" fill="#d5e1cb" rx="2"/><rect x="${x+2}" y="${Math.min(y(0),y(r.profit))}" width="16" height="${Math.max(1,Math.abs(y(0)-y(r.profit)))}" fill="#6f9e6a" rx="2"/><text x="${x}" y="${H-8}" text-anchor="middle" font-size="10" fill="#8b9f7d">${r.quarter?r.quarter+'분기':'기준'}</text><title>${r.quarter||'기준'}분기 예상 ${r.expected_profit}억원 / 실제 ${r.profit}억원</title>`}).join('')}</svg><p class="hint center">연한 막대 · 당초 예상 이익　진한 막대 · 실제 이익</p>`}
function earnings(){
 const available=[...new Set((S.reports||[]).map(r=>r.quarter))].sort((a,b)=>b-a),q=earningsQ!==null&&available.includes(+earningsQ)?+earningsQ:available[0]||0;
 const rr=(S.reports||[]).filter(r=>r.quarter===q),r=rr.find(x=>x.asset===earningsAsset)||rr[0],a=asset(r?.asset||earningsAsset);
 if(!r)return emptyState('기업 재무정보를 준비하고 있어요.');
 let forecast=forecastFor(a.id,Math.min(4,q+1)),links=r.evidence_ids.map(id=>S.news.find(n=>n.id===id)).filter(Boolean);
 return `<div class="filter-bar"><div class="seg">${available.map(n=>`<button class="${q===n?'active':''}" onclick="earningsQ=${n};render()">${n?n+'분기 실적':'기준 실적'}</button>`).join('')}</div><select class="input" style="width:215px" aria-label="분석할 기업" onchange="earningsAsset=this.value;render()">${S.assets.filter(x=>x.type==='stock').map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)} · ${esc(x.sector)}</option>`).join('')}</select></div>${q===0?`<div class="notice" style="margin-bottom:18px">첫 실적 발표 전입니다. 아래 기준 실적과 현재 공개된 예상치를 살펴보고, 뉴스의 변화가 어떤 결과로 이어질지 생각해 보세요.</div>`:''}<div class="research-layout"><div class="stack"><div class="card"><div class="report-company">${companyAvatar(a)}<div><h2>${esc(a.name)}</h2><p class="sub">${a.id} · ${esc(a.sector)} · ${q?q+'분기 발표':'시작 기준'}</p></div><div class="right">${smallLink('기업 분석',`detail('${a.id}')`)}</div></div>${financialTiles(r)}${q?expectationsChart(r):`<div class="explain-box"><b>실적 발표 전에 공개된 ${forecast?.quarter||1}분기 예상</b><p>매출 ${billions(forecast?.revenue)} · 영업이익 ${billions(forecast?.profit)}<br>예상은 결과를 보장하지 않아요. 이후 뉴스와 실제 발표를 비교해 보세요.</p></div>`}${q<4?currentEstimatePanel(a.id,q+1):''}<div class="explain-box"><b>${icon('search')} 실적을 이렇게 읽어 보세요</b><p>${esc(r.explanation)}</p>${q?`<p>${esc(r.outlook)}</p>`:''}</div><details class="disclosure"><summary>지난 분기의 영업이익 추이</summary>${reportTrend(a.id)}</details></div><details class="card disclosure company-comparison"><summary>20개 기업 실적 비교 펼치기</summary><div class="section-title"><h2>${q?q+'분기 기업 실적 비교':'20개 기업 기준 실적'}</h2><span class="sub">단위: 가상 억원</span></div><div class="tablewrap"><table class="financial-table"><thead><tr><th>기업</th><th>매출</th><th>영업이익</th><th>이익률</th><th>발표 직전 기대 대비</th></tr></thead><tbody>${rr.map(x=>`<tr class="click-row" tabindex="0" onclick="earningsAsset='${x.asset}';render()" onkeydown="if(event.key==='Enter'){earningsAsset='${x.asset}';render()}"><td><b>${esc(asset(x.asset).name)}</b></td><td>${number(x.revenue)}</td><td>${number(x.profit)}</td><td>${Number(x.margin).toFixed(1)}%</td><td>${q?reportBadge(x):'<span class="sub">기준</span>'}</td></tr>`).join('')}</tbody></table></div></details></div><div class="stack"><div class="card"><div class="section-title"><h2>이번 실적과 연결된 단서</h2>${icon('link')}</div><p class="sub">분기 중 해당 기업에 어떤 소식이 있었나요?</p>${links.length?newsCards(links,true):emptyState('분기 중 기업 뉴스가 쌓이면 이곳에서 함께 확인할 수 있어요.')}</div><div class="research-prompt"><div class="eyebrow">THINK BEFORE YOU INVEST</div><p>매출과 이익이 함께 늘었나요?<br>기대했던 것보다 더 잘했나요?<br>부채와 현금은 어떻게 변했나요?</p><button class="text-btn" style="padding:12px 0 0" onclick="${S.role==='admin'?"go('players')":`openNoteComposer('${a.id}')`}">${S.role==='admin'?'학생의 판단 과정 살펴보기':'이 기업에 대한 내 생각 남기기'} ${icon('arrow')}</button></div></div></div><p class="hint" style="margin-top:18px">${q===0?'기준 실적은 게임을 시작할 때 제공되는 비교 자료입니다. ':''}모든 기업과 재무 수치는 교육용 가상 데이터입니다. 분기 실적은 6·12·18·24일차 시작에 공개되며, 가격 반응도 같은 날 반영됩니다.</p>`
}

function market(){
 const list=filteredMarketAssets();
 return `${marketCategories()}<div class="filter-bar"><div class="filter-left"><input aria-label="기업·상품 검색" class="input" placeholder="기업·상품 이름 검색" value="${esc(marketSearch)}" oninput="marketSearch=this.value;renderMarketResults()" id="market-search"><select class="input" aria-label="상품 산업 필터" onchange="marketSector=this.value;render()">${['전체','기술','항공','식품','의료·제약','미래사업'].map(k=>`<option value="${k}" ${marketSector===k?'selected':''}>${k==='전체'?'모든 산업':k}</option>`).join('')}</select></div>${isTeacherMarket()?'':`<button class="chip ${marketFilter==='watch'?'active':''}" onclick="marketFilter=marketFilter==='watch'?'all':'watch';render()">☆ 관심 상품</button>`}</div><div class="card" id="market-results">${marketTable(list)}</div><details class="disclosure"><summary>산업별 오늘의 흐름</summary>${sectorBoard()}</details><p class="hint">${isTeacherMarket()?'상품을 눌러 현재 가격과 차트, 뉴스, 실적을 살펴보세요.':'기업을 눌러 뉴스와 실적을 살펴보고, 현재 가격으로 거래할 수 있어요.'}</p>`;
}
function marketTable(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>상품</th><th>현재가</th><th>오늘 변동</th><th>최근 매출</th><th>영업이익률</th><th>실적</th>${isTeacherMarket()?'':'<th>관심</th>'}</tr></thead><tbody>${list.map(a=>{let r=latestReport(a.id);return `<tr style="cursor:pointer" onclick="detail('${a.id}')" tabindex="0" onkeydown="if(event.key==='Enter')detail('${a.id}')"><td><div class="flex" style="justify-content:flex-start;gap:11px">${companyAvatar(a)}<div><b>${esc(a.name)}</b><div class="sub" style="font-size:10px">${a.id} · ${risk[a.risk]}</div></div></div></td><td><b>${money(a.price)}</b></td><td class="${a.change>=0?'up':'down'}">${pct(a.change)}</td><td>${r?billions(r.revenue):'—'}</td><td>${r?Number(r.margin).toFixed(1)+'%':'—'}</td><td>${r?.quarter?reportBadge(r):r?'<span class="tag">기준 실적</span>':'<span class="sub">금융상품</span>'}</td>${isTeacherMarket()?'':`<td><button class="watch-star ${(S.watchlist||[]).includes(a.id)?'on':''}" aria-label="${esc(a.name)} 관심 ${S.watchlist?.includes(a.id)?'해제':'등록'}" aria-pressed="${(S.watchlist||[]).includes(a.id)}" onclick="event.stopPropagation();toggleWatch('${a.id}')">${(S.watchlist||[]).includes(a.id)?'★':'☆'}</button></td>`}</tr>`}).join('')}</tbody></table></div>`:emptyState('조건에 맞는 상품이 없어요.')}
function renderMarketResults(){const el=$('#market-results');if(el)el.innerHTML=marketTable(filteredMarketAssets())}
async function toggleWatch(id){if(S.role!=='player')return toast('관심 목록은 학생 계정에서 관리해요.');try{let enabled=!(S.watchlist||[]).includes(id);await api('/watchlist',{method:'POST',body:{asset:id,enabled}});S.watchlist=enabled?[...(S.watchlist||[]),id]:S.watchlist.filter(x=>x!==id);render()}catch(e){toast(e.message)}}
function priceExplanation(a){
 const p=a.price_context;if(!p)return '';
 const pp=n=>`${n>=0?'+':''}${Number(n).toFixed(2)}%p`;
 const links=(p.news_ids||[]).map(id=>S.news.find(n=>n.id===id)).filter(Boolean);
 return `<details class="price-explanation"><summary>오늘 ${pct(a.change)} · 어떤 요인이 반영됐나요?</summary><div class="price-factors">${[['뉴스 반영',p.news],['실적 발표',p.earnings],['시장·그 밖의 요인',p.other]].map(([label,value])=>`<div><span>${label}</span><b class="${value>=0?'up':'down'}">${pp(value)}</b></div>`).join('')}</div><p class="hint">${p.breaking?'속보는 오늘 시작 가격에 함께 반영됐어요.':'새 뉴스에 대한 반응은 다음 1~3거래일에 나누어 반영돼요.'} 시장·업종 흐름, 기업별 변동과 가격 제한도 함께 작용해요. 이미 확정된 오늘 등락의 설명이며, 다음 날 수익을 뜻하지 않아요.</p>${links.length?`<div class="price-evidence"><span class="sub">오늘 가격에 반영된 기사</span>${links.map(n=>`<button class="text-btn" onclick="openArticle(${n.id})">${icon('link')} ${esc(newsTitle(n))}</button>`).join('')}</div>`:''}</details>`;
}
function detailView(){
 const a=asset(selected);if(!a)return market();
 const r=latestReport(selected),links=relatedAssetNews(a,8),h=(S.holdings||[]).find(h=>h.asset===selected),disabled=S.role!=='player'||S.demo||S.room.phase!=='trading';
 const subset=range==='all'?history:history.slice(-(range==='7'?7:14)),reportQ=r?.quarter||0;
 const tabs=[['chart','가격 차트'],...(a.type==='etf'?[['composition','구성 종목·비중']]:[]),['news',a.type==='etf'?'관련 뉴스':'뉴스·사업'],...(a.type==='stock'?[['results','분기 실적']]:[])];
 if(!tabs.some(([k])=>k===companyTab))companyTab='chart';
 return `<div id="trade-meta" data-asset="${selected}"></div><div class="quarter-strip"><button class="text-btn" onclick="go('market')">← 투자 목록</button><span>${esc(a.sector)} · ${risk[a.risk]}</span>${S.role==='player'?`<button class="text-btn" onclick="toggleWatch('${selected}')">${(S.watchlist||[]).includes(selected)?'★ 관심 기업':'☆ 관심 등록'}</button>`:''}</div>
 <section class="card company-heading"><div class="report-company">${companyAvatar(a)}<div><h2>${esc(a.name)}</h2><span class="sub">${a.id} · ${a.type==='stock'?'기업 주식':a.type==='etf'?'ETF':a.type==='bond'?'채권':'금'}</span></div><div class="right"><strong class="big">${money(a.price)}</strong><div class="${a.change>=0?'up':'down'}">오늘 ${pct(a.change)}</div></div></div><p class="company-description">${esc(a.description||'')}</p>${r?`<div class="company-snapshot"><span>${reportQ?reportQ+'분기':'기준'} 영업이익 <b>${billions(r.profit)}</b></span>${reportQ?`<span>전 분기 대비 <b>${pct(r.profit_growth)}</b></span>${reportBadge(r)}`:'<span>실적 발표 전 · 뉴스를 보며 다음 분기를 예상해 보세요.</span>'}</div>`:''}${priceExplanation(a)}${a.etf_composition?`<div class="etf-summary"><span>${a.etf_composition.company_count}개 기업 · ${a.etf_composition.sectors.length}개 업종${a.etf_composition.multiplier!==1?' · 일일 '+a.etf_composition.multiplier+'배':''}</span><button class="text-btn" onclick="companyTab='composition';render()">구성 종목·비중 보기 ${icon('chevron')}</button></div>`:''}</section>
 <div class="company-workspace"><section class="card company-research"><div class="section-tabs company-tabs" aria-label="기업 정보">${tabs.map(([k,v])=>`<button class="${companyTab===k?'active':''}" aria-pressed="${companyTab===k}" onclick="companyTab='${k}';render()">${v}</button>`).join('')}</div>
 ${companyTab==='composition'?etfCompositionPanel(a):companyTab==='news'?a.type==='etf'?etfRelatedNewsPanel(a):`<div class="section-title"><h2>이 기업의 최근 소식</h2><span class="sub">전망과 확인된 사실을 구분해 보세요.</span></div>${newsCards(links,true)}${a.type==='stock'?`<details class="disclosure"><summary>진행 중인 장기 사업 보기</summary>${projectBoard(selected)}</details>`:`<p class="notice">${a.type==='etf'?'여러 기업에 나누어 투자하는 상품이에요. 2배·인버스 상품은 하루 수익률을 기준으로 움직여 여러 날의 누적 수익률은 단순한 2배가 아닐 수 있어요.':a.type==='bond'?(S.bond_policy?.mode==='legacy_annual'?'이미 결산한 게임의 채권 이자는 기존 연말 지급 내역을 유지합니다.':'채권의 시장가격은 오르거나 내릴 수 있어요. 이자는 매일 마감 시 보유 수량으로 쌓이고, 3·6·9·12·15·18·21·24일차 마감 때 현금으로 지급돼요.'):'금 가격도 시장 상황에 따라 오르거나 내릴 수 있어요.'}</p>`}`:companyTab==='results'?r?`${financialTiles(r)}${reportQ?expectationsChart(r):''}${reportQ<4?currentEstimatePanel(selected,reportQ+1):''}<div class="explain-box"><b>실적에서 확인할 점</b><p>${esc(r.explanation)}</p></div><button class="text-btn" onclick="openReport('${selected}')">다른 분기·기업과 비교하기 ${icon('arrow')}</button>`:emptyState('아직 공개된 실적이 없어요.'):`<div class="section-title"><h2>하루 단위 가격 차트</h2><div class="seg">${[['7','최근 7일'],['14','14일'],['all','전체']].map(([k,v])=>`<button class="${range===k?'active':''}" onclick="range='${k}';pickedDay=null;render()">${v}</button>`).join('')}</div></div>${svgchart(subset)}<p class="hint">가격은 하루 한 번 확정돼요. 봉의 고가·저가는 교육용 모의 값입니다.</p>`}</section>
 ${isTeacherMarket()?teacherMarketPanel(a):`<aside class="card trade-panel"><h2>거래하기</h2><p class="sub">현재 가격으로 즉시 반영돼요.</p><div class="trade-balances"><span>사용 가능 <b>${money(S.player?.cash||0)}</b></span><span>보유 <b>${h?.qty||0}주</b></span></div>${h?`<div class="position-average"><span>평균매수가 <small>매수 수수료 포함</small></span><b>${unitMoney(holdingAverage(h))}</b></div>`:''}${a.type==='bond'?bondTerms(a):''}<div class="seg jump"><button id="buyBtn" class="${currentSide==='buy'?'active':''}" onclick="orderSide('buy')">매수</button><button id="sellBtn" class="${currentSide==='sell'?'active':''}" onclick="orderSide('sell')">매도</button></div>
 <label for="qty">수량</label><input class="input" id="qty" type="number" min="1" step="1" value="1" oninput="updateOrderTotal()"><div class="trade-costs"><div><span>거래 금액</span><b id="orderGross">${money(a.price)}</b></div><div><span>수수료 (${feeRateLabel()})</span><b id="orderFee">${money(quoteFee(a.price))}</b></div><div class="settlement"><span id="settlementLabel">${currentSide==='buy'?'총 결제액':'받을 금액'}</span><b id="orderTotal">${money(a.price+(currentSide==='buy'?1:-1)*quoteFee(a.price))}</b></div></div><p class="fee-disclosure">매수·매도 각각 ${feeRateLabel()} · 최소 1원 · 원 단위 반올림</p><details class="disclosure fee-details"><summary>거래비용 안내</summary><p class="hint">주식·ETF·채권·금에 공통으로 적용하는 게임 수수료예요. 예금에는 거래 수수료가 없고, 이 게임에서는 세금을 부과하지 않아요.</p></details>
 <label for="reason">판단 이유 한 줄</label><textarea class="input" id="reason" rows="2" minlength="2" maxlength="500" placeholder="뉴스나 실적을 보고 어떤 판단을 했나요?"></textarea><p class="hint">이 이유가 투자 기록에 저장돼요. 나중에 배운 점을 이어 쓸 수 있어요.</p>
 <details class="disclosure trade-evidence-panel" ${tradeDrafts[selected]?.ids?.length?'open':''}><summary>참고한 기사 연결 <span class="sub">선택 · 최대 5건</span></summary>${evidenceSelector('trade-evidence',selected)}</details>
 <button class="btn dark trade-submit" ${disabled?'disabled':''} onclick="place()">${currentSide==='buy'?'매수':'매도'}하고 이유 저장</button>${S.room.phase!=='trading'?'<p class="notice">지금은 거래가 마감됐어요.</p>':S.demo?'<p class="hint">읽기 전용 체험입니다. 게임방에서 거래할 수 있어요.</p>':S.role==='admin'?'<p class="hint">교사에게는 읽기 전용으로 표시됩니다.</p>':''}</aside>`}</div>`;
}
function evidenceSelector(id,aid,preselected=null){let relevant=(asset(aid)?.type==='etf'?relatedAssetNews(asset(aid),null):S.news.filter(n=>newsMatchesAsset(n,asset(aid))||n.sector===asset(aid)?.sector||n.sector==='전체')).filter(n=>n.kind!=='briefing');if(preselected)relevant.sort((x,y)=>Number(y.id===preselected)-Number(x.id===preselected));relevant=relevant.slice(0,14);return relevant.length?`<div class="evidence-checks" id="${id}">${relevant.map(n=>`<label class="evidence-option"><input type="checkbox" value="${n.id}" ${preselected===n.id?'checked':''} ${S.role==='admin'?'disabled':''}><span><span style="color:#a2b098;font-size:9px">${n.day}일차 · ${esc(n.certainty||'기사')}</span><br>${esc(newsTitle(n))}</span></label>`).join('')}</div>`:`<div class="notice">아직 관련 기사가 없어요. 기업 정보나 상품 구조를 바탕으로 판단해 보세요.</div>`}
function pickedEvidence(id){return [...document.querySelectorAll('#'+id+' input:checked')].map(el=>+el.value)}
async function place(){
 const qty=+$('#qty').value,reason=$('#reason').value.trim(),evidence_ids=pickedEvidence('trade-evidence'),a=asset(selected);
 if(!Number.isInteger(qty)||qty<1)return toast('수량은 1 이상의 정수로 입력하세요.');if(reason.length<2)return toast('판단 이유를 한 줄 적어주세요.');if(evidence_ids.length>5)return toast('근거 기사는 최대 5건까지 선택해요.');
 const gross=a.price*qty,fee=quoteFee(gross),settlement=gross+(currentSide==='buy'?fee:-fee);
 if(!confirm(`${a.name} ${qty}주 ${currentSide==='buy'?'매수':'매도'}\n거래 금액 ${money(gross)}\n수수료 (${feeRateLabel()}) ${money(fee)}\n${currentSide==='buy'?'총 결제액':'받을 금액'} ${money(settlement)}${a.risk==='high'?'\n가격 변동이 큰 상품이에요.':''}`))return;
 const button=$('.trade-submit');if(button)button.disabled=true;
 try{const r=await api('/orders',{method:'POST',body:{asset:selected,side:currentSide,qty,reason,evidence_ids,expected_day:S.room.day,expected_price:a.price}});$('#reason').value='';document.querySelectorAll('#trade-evidence input').forEach(el=>el.checked=false);delete tradeDrafts[selected];tab='portfolio';await refresh();window.scrollTo(0,0);toast(r.message+` 수수료 ${money(r.fee)}.`+(r.selection_resumed?' 오늘 상태는 선택 중으로 바뀌었어요.':''))}catch(e){if(button)button.disabled=false;await refresh();toast(e.message)}
}
function journal(){
 const a=asset(journalAsset)||asset('HBEL'),canWrite=S.role==='player'&&!S.demo&&S.room.phase==='trading',notes=S.notes||[],orders=(S.orders||[]).filter(o=>!o.is_final_liquidation),linked=new Set(notes.map(n=>n.order_id).filter(Boolean));
 let records=[...notes.map(n=>({...n,trade:orders.find(o=>o.id===n.order_id)||(n.order_id&&n.order_side?{id:n.order_id,side:n.order_side,qty:n.order_qty,price:n.order_price,fee:n.order_fee}:null)})),...orders.filter(o=>o.status==='filled'&&!linked.has(o.id)).map(o=>({id:null,order_id:o.id,day:o.filled_day,asset:o.asset,thesis:o.reason,risk:'',horizon:'',evidence_ids:parseEvidence(o.evidence_ids),reflection:'',entry_price:o.price,created:o.created,trade:o}))];
 records.sort((a,b)=>b.day-a.day||String(b.created).localeCompare(String(a.created)));
 const shown=records.filter(n=>journalFilter!=='review'||!n.reflection);
 return `<div class="record-heading"><div><b>판단과 거래를 함께 모았어요.</b><p class="sub no-margin">거래 이유는 자동으로 저장돼요. 실적을 보고 배운 점을 이어 써 보세요.</p></div><button class="btn secondary sm" ${!canWrite?'disabled':''} onclick="openNoteComposer()">${icon('plus')} 거래 없이 생각 남기기</button></div>
 ${noteComposerOpen?`<section class="card note-composer"><div class="section-title"><h2>나의 판단 남기기</h2><button class="text-btn" onclick="noteComposerOpen=false;render()">접기</button></div><form onsubmit="event.preventDefault();saveNote()"><label for="note-asset">기업·상품</label><select class="input" id="note-asset" onchange="journalAsset=this.value;noteDraft.ids=[];document.querySelectorAll('#note-evidence input').forEach(el=>el.checked=false);evidenceDraft=null;render()">${S.assets.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><label for="note-thesis">어떤 판단을 했나요?</label><textarea class="input" id="note-thesis" minlength="5" maxlength="700" rows="3" oninput="noteDraft.thesis=this.value" required ${!canWrite?'disabled':''}>${esc(noteDraft.thesis)}</textarea><details class="disclosure" ${noteDraft.risk||evidenceDraft?'open':''}><summary>걱정거리와 근거 더하기 <span class="sub">선택</span></summary><label for="note-risk">생각과 다르게 될 수 있는 점</label><textarea class="input" id="note-risk" maxlength="500" rows="2" oninput="noteDraft.risk=this.value">${esc(noteDraft.risk)}</textarea><label for="note-horizon">다시 확인할 시점</label><select class="input" id="note-horizon" onchange="noteDraft.horizon=this.value">${horizonOptions(noteDraft.horizon)}</select><label>참고한 기사 · 최대 5건</label>${evidenceSelector('note-evidence',a.id,evidenceDraft)}</details><button class="btn dark" type="submit" ${!canWrite?'disabled':''}>판단 저장</button></form></section>`:''}
 <div class="filter-bar"><div class="seg"><button class="${journalFilter==='all'?'active':''}" onclick="journalFilter='all';render()">전체 기록 ${records.length}</button><button class="${journalFilter==='review'?'active':''}" onclick="journalFilter='review';render()">돌아볼 기록</button></div><span class="sub">처음의 판단은 보관하고, 배운 점을 덧붙여요.</span></div>
 <div class="record-list">${shown.map(n=>{const a=asset(n.asset),t=n.trade;return `<article class="note-card"><div class="note-meta"><span>${n.day}일차 · ${t?`${t.side==='buy'?'매수':'매도'} ${t.qty}주 · ${money(t.qty*t.price)}`:'거래 없이 남긴 판단'}</span><button class="text-btn" onclick="detail('${n.asset}')">${esc(a?.name||n.asset)} ${icon('chevron')}</button></div><h3>${esc(n.thesis)}</h3>${t?`<p class="record-trade-cost sub">수수료 ${money(t.fee||0)} · ${t.side==='buy'?'결제':'수령'} ${money(t.price*t.qty+(t.side==='buy'?1:-1)*(t.fee||0))}</p>`:''}${n.risk?`<p class="note-risk"><b>걱정한 점</b> ${esc(n.risk)}</p>`:''}<div class="note-evidence">${(n.evidence_ids||[]).map(id=>{const x=S.news.find(x=>x.id===id);return x?`<button onclick="openArticle(${id})">${icon('link')} ${esc(newsTitle(x))}</button>`:''}).join('')}</div>${n.reflection?`<div class="reflection-box"><b>돌아보며 배운 점</b><p class="no-margin">${esc(n.reflection)}</p></div>`:''}<div class="record-footer"><span class="sub">${n.horizon?`다시 확인: ${esc(n.horizon)}`:''}</span>${S.role==='player'?`<button class="btn secondary sm" ${S.demo?'disabled':''} onclick="${n.id?`reflectionModal(${n.id})`:`reflectTrade(${n.order_id})`}">${n.reflection?'돌아보기 수정':'배운 점 이어 쓰기'}</button>`:''}</div></article>`}).join('')||emptyState(journalFilter==='review'?'아직 돌아보지 않은 기록이 없어요.':'첫 거래의 이유가 여기에 자동으로 남아요. 거래 없이 생각을 남겨도 좋아요.')}</div>`;
}
async function saveNote(){
 const evidence_ids=pickedEvidence('note-evidence');if(evidence_ids.length>5)return toast('근거 기사는 최대 5건까지 선택해요.');
 try{await api('/notes',{method:'POST',body:{asset:$('#note-asset').value,thesis:$('#note-thesis').value,risk:$('#note-risk')?.value||'',horizon:$('#note-horizon')?.value||'다음 실적 발표까지',evidence_ids}});$('#note-thesis').value='';if($('#note-risk'))$('#note-risk').value='';document.querySelectorAll('#note-evidence input').forEach(el=>el.checked=false);noteDraft={thesis:'',risk:'',horizon:'다음 실적 발표까지',ids:[]};evidenceDraft=null;noteComposerOpen=false;await refresh();toast('판단을 저장했어요. 다음 뉴스와 실적에서 확인해 보세요.')}catch(e){toast(e.message)}
}
function reflectionModal(id){
 const n=S.notes.find(n=>n.id===id);if(!n)return;
 showModal(`<div class="modal-titlebar"><span>판단 돌아보기</span><button class="modal-x" aria-label="닫기" onclick="closeModal()">${icon('close')}</button></div><h2>내 판단을 다시 살펴봐요.</h2><div class="notice"><b>${n.day}일차의 판단 · ${esc(asset(n.asset)?.name)}</b><br>${esc(n.thesis)}</div><form onsubmit="event.preventDefault();saveReflection(${id})"><label for="reflection">무엇이 맞았고, 무엇을 놓쳤나요?</label><textarea class="input" id="reflection" rows="4" maxlength="1000" minlength="5" placeholder="새 뉴스나 실적을 보고 배운 점을 적어 보세요." required>${esc(n.reflection)}</textarea><details class="disclosure"><summary>걱정거리·다시 확인할 시점 덧붙이기</summary><label for="reflection-risk">걱정한 점</label><textarea class="input" id="reflection-risk" maxlength="500" rows="2">${esc(n.risk)}</textarea><label for="reflection-horizon">다시 확인할 시점</label><select class="input" id="reflection-horizon">${horizonOptions(n.horizon)}</select></details><div class="modal-actions"><button type="submit" class="btn dark">돌아보기 저장</button></div></form>`);
}
async function saveReflection(id){try{await api('/notes/'+id,{method:'PATCH',body:{reflection:$('#reflection').value,risk:$('#reflection-risk').value,horizon:$('#reflection-horizon').value}});closeModal();await refresh();toast('배운 점을 저장했어요.')}catch(e){toast(e.message)}}
let progressionBusy=false,progressionPolling=false,clockBase=null,transitionTimer=null;
function syncClassClock(data){
 if(!data||!S)return;
 if(data.revision<(S.progression?.revision||0))return;
 S.progression=data;
 if(Number.isFinite(data.server_time))clockBase={server:data.server_time*1000,local:performance.now()};
 updateClassClock();
}
function clockRemaining(){
 const p=S?.progression;if(!p?.deadline||!clockBase)return 0;
 return Math.max(0,Math.ceil((p.deadline*1000-clockBase.server-(performance.now()-clockBase.local))/1000));
}
function classClock(){
 const p=S?.progression;if(!p?.timer_enabled||S.room.phase==='finished')return '';
 return `<aside class="classroom-timer ${p.deadline?'':'paused'}" aria-label="학급 선택 시간"><div>${icon('clock')}<span>${p.deadline?'오늘의 선택 시간':'타이머 일시정지'}</span><strong id="classroom-countdown" role="timer" aria-live="off"></strong></div><p id="classroom-timer-hint">${p.deadline?(S.room.day===24?'시간이 끝나면 최종 결산합니다.':'시간이 끝나면 다음 날이 시작됩니다.'):'교사가 다음 날을 열면 새 시간이 시작됩니다.'}</p></aside>`;
}
function updateClassClock(){
 const root=$('#classroom-clock');if(!root)return;
 const p=S?.progression,visible=!!p?.timer_enabled&&S.room.phase!=='finished';
 if(!visible){if(root.firstChild)root.replaceChildren();return}
 if(visible!==!!root.querySelector('.classroom-timer')||Boolean(root.querySelector('.paused'))!==!p?.deadline)root.innerHTML=classClock();
 const el=$('#classroom-countdown');if(!el)return;
 if(!p.deadline){el.textContent='토론 중';return}
 const seconds=clockRemaining();el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');
 root.querySelector('.classroom-timer').classList.toggle('ending',seconds<=30);
 if(!seconds)$('#classroom-timer-hint').textContent='시간 종료 · 다음 화면을 준비하고 있어요.';
}
function progressionControls(){
 const p=S.progression||{auto_ready:0,timer_enabled:0,timer_seconds:180},finished=S.room.phase==='finished';
 return `<section class="card progression-controls"><h2>자동 진행과 시간 모드</h2><label class="auto-ready-toggle"><input type="checkbox" id="auto-ready" ${p.auto_ready?'checked':''} ${finished||progressionBusy?'disabled':''} onchange="setAutoReady(this.checked)"><span><b>모든 학생이 선택 완료하면 자동으로 다음 날</b><small>참가 학생이 1명 이상일 때 적용해요. 켤 때 이미 전원 완료 상태여도 바로 진행합니다.</small></span></label><div class="timer-settings"><label for="timer-minutes">하루 선택 시간</label><div class="timer-input-row"><input class="input" id="timer-minutes" type="number" min="1" max="120" step="1" value="${p.timer_seconds/60}" ${finished?'disabled':''}><span>분</span><button class="btn dark" id="timer-start" onclick="startClassTimer()" ${finished||S.room.phase!=='trading'||progressionBusy?'disabled':''}>${p.timer_enabled?'지금부터 다시 시작':'타이머 시작'}</button><button class="btn secondary" id="timer-stop" onclick="stopClassTimer()" ${finished||!p.timer_enabled||progressionBusy?'disabled':''}>시간 모드 끄기</button></div><p class="hint">시작한 순간부터 모든 화면에 타이머가 표시돼요. 매일 같은 시간으로 반복하며, 완료하지 않은 학생이 있어도 시간이 끝나면 자동으로 넘어갑니다. 24일차는 최종 결산해요.</p><p class="hint">두 기능을 함께 켜면 먼저 충족한 조건으로 진행합니다. ‘마감만 하고 토론하기’는 타이머를 일시정지하고, 다음 날을 열면 새 시간을 시작합니다. 초기화하면 두 기능이 꺼집니다.</p></div></section>`;
}
async function saveProgression(body){
 if(progressionBusy)return;progressionBusy=true;
 document.querySelectorAll('.progression-controls input,.progression-controls button').forEach(el=>el.disabled=true);
 try{await api('/admin/progression',{method:'POST',body:{...body,expected_day:S.room.day,expected_phase:S.room.phase}});await refresh();toast('자동 진행 설정을 적용했어요.')}catch(e){await refresh();toast(e.message)}finally{progressionBusy=false;if(S?.role==='admin'&&tab==='admin')render()}
}
async function setAutoReady(value){await saveProgression({auto_ready:value})}
async function startClassTimer(){const minutes=Number($('#timer-minutes').value);if(!Number.isInteger(minutes)||minutes<1||minutes>120)return toast('1~120분 사이의 정수를 입력해 주세요.');await saveProgression({timer_action:'start',minutes})}
async function stopClassTimer(){await saveProgression({timer_action:'stop'})}
async function pollProgression(){
 if(progressionPolling||!S||!token||S.demo||document.visibilityState==='hidden'||S.room.phase==='finished')return;
 const roomId=S.room.id;progressionPolling=true;
 try{
  const data=await api('/progression');if(!S||S.room.id!==roomId||!Number.isInteger(data.day)||!Number.isInteger(data.generation)||data.generation<S.room.generation)return;
  if(data.generation===(S.room.generation||0)&&data.day<S.room.day)return;
  if(data.generation!==(S.room.generation||0)||data.day!==S.room.day||data.phase!==S.room.phase){await refresh(true);return}
  syncClassClock(data);
 }catch{}finally{progressionPolling=false}
}
function closeDayTransition(){clearTimeout(transitionTimer);$('#day-transition')?.remove();if($('#app'))$('#app').inert=false}
function showDayTransition(room,restarted=false){
 if(S?.role!=='player'||S.demo)return;closeDayTransition();
 const quarter=Math.ceil(room.day/6),release=quarter*6,finished=room.phase==='finished';
 const headline=finished?'투자 종료 · 최종 결산':`${quarter}분기 · ${room.day}일차`;
 const detail=finished?'나의 투자와 판단 기록을 돌아보세요.':room.day===release?`${quarter}분기 실적 발표 · 오늘 공개`:`${quarter}분기 실적 발표까지 D-${release-room.day}`;
 const node=document.createElement('div');node.id='day-transition';node.className='day-transition';node.setAttribute('role','status');node.setAttribute('aria-live','polite');
 node.innerHTML=`<div class="day-transition-inner"><span>${restarted?'새로운 투자 시작':finished?'YEAR COMPLETE':'A NEW TRADING DAY'}</span><h2>${headline}</h2><p>${detail}</p><i aria-hidden="true"></i><button onclick="closeDayTransition()" aria-label="날짜 전환 화면 닫기">계속하기</button></div>`;
 document.body.appendChild(node);$('#app').inert=true;
 transitionTimer=setTimeout(closeDayTransition,window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?900:1900);
}
function moodHelp(){return `<details class="disclosure mood-help"><summary>뉴스 분위기는 어떻게 적용되나요?</summary><p>다음 날 새 기업 뉴스가 긍정적으로 나올 확률을 바꿔요. 긍정 68% · 중립 50% · 부정 30%이며, 나머지는 부정 방향입니다. 중립은 주가가 안 움직인다는 뜻이 아니에요. 바꾸지 않으면 이후에도 같은 분위기를 유지합니다.</p><p>선택한 한 업종의 산업 전망에도 긍정·중립·부정 방향을 반영해요. 예를 들어 3일차에 선택하면 4일차 새 뉴스부터 달라지고, 그 뉴스의 가격 반응은 5~7일차에 나뉘어요. 새 뉴스의 기대 변화는 이후 1~3일 가격에 나뉘고, 사업의 매출·비용은 기사에 적힌 단기·다음 분기·연말 기간에 반영됩니다.</p><p>이미 나온 기사와 진행 중인 사건의 성공·실패를 다시 뽑지는 않아요. 시장·다른 뉴스·실적이 함께 작용하므로 긍정에서도 하락하고 부정에서도 상승할 수 있어요. 속보의 횟수·날짜도 분위기로 바꾸지 않습니다.</p></details>`}
function teacherHome(){
 if(S.room.phase==='finished'&&S.finale)return finaleView();
 const ps=S.participants||[],ready=ps.filter(p=>p.day_ready).length,finished=S.room.phase==='finished';
 return (S.room.day===24?'<p class="final-day-notice">24일차 마감 시 모든 보유 거래상품을 마지막 시세로 자동 매도합니다. 매도 수수료와 마지막 채권 이자를 반영한 후 최종 결과를 확정합니다.</p>':'')+`<section class="card classroom-control ${S.all_ready?'all-ready':''}"><div class="section-title"><div><span class="sub">${S.room.day}일차 / 24일</span><h2>${finished?'가상의 1년을 마쳤습니다.':S.all_ready?'모든 학생이 선택을 마쳤어요.':S.room.phase==='closed'?'토론을 위해 잠시 멈췄어요.':'학생들의 판단을 기다리고 있어요.'}</h2></div><span class="ready-count">${ready}<small> / ${ps.length}명 완료</small></span></div><div class="ready-list">${ps.map(p=>`<button class="chip ${p.day_ready?'active':''}" onclick="tab='preview';loadPreview(${p.id})">${p.day_ready?'✓':'○'} ${esc(p.name)}</button>`).join('')||'<p class="sub">아래 참가 코드와 QR로 학생을 초대해 주세요.</p>'}</div><div class="classroom-actions">${finished?`<button class="btn secondary" onclick="go('players')">학생들의 판단 돌아보기</button>`:`<button class="btn dark advance-button" data-admin-action onclick="adminAction('advance')" ${adminBusy?'disabled':''}>${S.room.day===24?'24일 마치고 최종 결산':S.room.phase==='closed'?'다음 날 열기':'오늘 마치고 다음 날 열기'} ${icon('arrow')}</button>${S.room.phase==='trading'&&S.room.day<24?`<button class="text-btn" data-admin-action onclick="adminAction('close')" ${adminBusy?'disabled':''}>마감만 하고 토론하기</button>`:''}`}<span class="sub">${finished?'기존 기록은 계속 볼 수 있어요.':S.progression?.timer_enabled||S.progression?.auto_ready?'자동 진행이 켜져 있어요. 설정에서 바꿀 수 있어요.':'다음 날은 선생님이 직접 엽니다.'}</span></div>${!finished?`<div class="mood-control"><span>다음 날 뉴스 분위기</span><div class="seg">${[['positive','긍정'],['neutral','중립'],['negative','부정']].map(([k,v])=>`<button class="${(S.room.mood||'neutral')===k?'active':''}" onclick="setMarketMood('${k}')">${v}</button>`).join('')}</div><span class="hint">분위기와 다른 소식도 나올 수 있어요.</span></div>${moodHelp()}`:''}</section>
 <div class="today-layout"><div class="stack"><section class="card"><div class="section-title"><h2>오늘 함께 읽을 뉴스</h2>${smallLink('뉴스 전체',"go('news')")}</div>${newsCards(selectHighlights(S.news.filter(n=>n.day===S.room.day)),true)}</section><section class="card"><div class="section-title"><h2>우리 반 판단 기록</h2>${smallLink('학생별 확인',"go('players')")}</div><p class="sub no-margin">근거를 연결한 거래 ${ps.reduce((n,p)=>n+(p.evidence_trades||0),0)}건 · 돌아보기 ${ps.reduce((n,p)=>n+(p.reflection_count||0),0)}건</p></section></div><aside class="stack"><section class="card"><div class="section-title"><h2>학생 참가</h2><strong class="room-code">${esc(S.room.code)}</strong></div><div id="shareBox"><p class="sub">참가 QR을 준비하고 있어요.</p></div></section><section class="card"><div class="section-title"><h2>분기 실적</h2>${smallLink('실적 보기',"go('earnings')")}</div>${calendarCards()}</section>${npcPanel(true)}</aside></div>`;
}
const participantColumns=[['name','학생'],['rank','순위'],['day_ready','오늘 선택'],['net','총자산'],['profit','수익률'],['read_count','기사 열람'],['evidence_trades','근거 연결 거래'],['note_count','판단 기록'],['reflection_count','돌아보기']];
let participantSort={key:'name',order:'asc'};
function sortParticipants(key){
 if(!participantColumns.some(([k])=>k===key))return;
 participantSort={key,order:participantSort.key===key?(participantSort.order==='asc'?'desc':'asc'):key==='name'||key==='rank'?'asc':'desc'};render();
}
function sortedParticipants(){
 const {key,order}=participantSort,direction=order==='asc'?1:-1;
 const value=p=>key==='name'?p.name:key==='rank'?(p.ranking?.rank??Infinity):Number(p[key]||0);
 return [...(S.participants||[])].sort((a,b)=>direction*(key==='name'?value(a).localeCompare(value(b),'ko'):(value(a)-value(b)))||a.name.localeCompare(b.name,'ko')||a.id-b.id);
}
function participants(){
 const ps=sortedParticipants();
 return `<div class="notice" style="margin-bottom:20px">학생의 수익과 판단 과정을 함께 살펴보세요. 기사 열람 수는 이해도를 뜻하지 않으며, 기록 개수와 수익률만으로 학습을 평가하지 않습니다.</div><div class="card"><div class="section-title"><div><h2>학생별 금융 활동과 학습 기록</h2><p class="sub">항목 이름을 누르면 오름차순·내림차순으로 바뀝니다. 수익률은 교사의 현금 지급·차감을 제외해요.</p></div><span class="sub">${ps.length}명 참가</span></div>${ps.length?`<div class="tablewrap"><table class="participant-table"><thead><tr>${participantColumns.map(([key,label])=>`<th scope="col" aria-sort="${participantSort.key===key?(participantSort.order==='asc'?'ascending':'descending'):'none'}"><button class="table-sort ${participantSort.key===key?'active':''}" onclick="sortParticipants('${key}')" aria-label="${label}, ${(participantSort.key===key?participantSort.order==='asc':key!=='name'&&key!=='rank')?'내림차순':'오름차순'} 정렬">${label}<span aria-hidden="true">${participantSort.key===key?(participantSort.order==='asc'?'↑':'↓'):'↕'}</span></button></th>`).join('')}<th scope="col">살펴보기</th></tr></thead><tbody>${ps.map(p=>`<tr data-player-id="${p.id}"><td><b>${esc(p.name)}</b></td><td>${p.ranking?`${p.ranking.tied?'공동 ':''}${p.ranking.rank}위`:'—'}</td><td><span class="${p.day_ready?'badge':'tag'}">${p.day_ready?'완료':'선택 중'}</span></td><td>${money(p.net)}</td><td class="${p.profit>=0?'up':'down'}">${pct((p.profit||0)/S.room.start_cash*100)}</td><td>${p.read_count||0}건</td><td>${p.evidence_trades||0}건</td><td>${p.note_count||0}건</td><td>${p.reflection_count||0}건</td><td><button class="btn secondary sm" onclick="tab='preview';loadPreview(${p.id})">학생 화면</button> <button class="btn ghost sm" onclick="cashPrompt(${p.id})">현금 조정</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('아직 참가한 학생이 없어요.')}</div>`;
}
function cashPrompt(id){let p=S.participants.find(x=>x.id===id);if(p)changeCash(id,p.name)}
async function loadPreview(pid){if(!pid){previewPid=null;previewData=null;return render()}try{previewPid=+pid;previewData=await api('/admin/student/'+previewPid);previewTab='home';render()}catch(e){toast(e.message)}}
function adminPreview(){
 const names=S.participants||[],chooser=`<div class="card preview-chooser"><div class="flex wrap"><div><h2>학생 화면 보기</h2><p class="sub no-margin">실제 자산과 기록을 읽기 전용으로 확인해요.</p></div><select class="input" aria-label="미리볼 학생" onchange="loadPreview(this.value)"><option value="">학생 선택</option>${names.map(p=>`<option value="${p.id}" ${+previewPid===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class="text-btn" onclick="go('players')">학생 현황으로</button></div></div>`;
 if(!previewData)return chooser+emptyState(names.length?'살펴볼 학생을 선택해 주세요.':'학생이 참가하면 실제 화면을 확인할 수 있어요.');
 const saved=S,pv=previewData;let body='',menu='';S={...S,...pv,role:'admin'};
 try{menu=`<nav class="section-tabs preview-menu" aria-label="학생 주 메뉴">${studentMenu.map(([k,v])=>`<button class="${navGroup(previewTab,false)===k?'active':''}" onclick="go('${k}')">${v}</button>`).join('')}</nav>`;body=dayFinishPanel()+sectionTabs(true)+({home:playerHome,news,earnings,market,portfolio,journal,bank,orders,detail:detailView}[previewTab]||playerHome)()}finally{S=saved}
 return chooser+`<div class="preview-banner">${icon('eye')} ${esc(pv.player.name)} 학생의 화면 · 교사 읽기 전용</div>`+menu+body;
}
function adminOrders(){return `<div class="card"><div class="section-title"><h2>거래와 투자 근거</h2><span class="sub">최근 60건</span></div>${S.all_orders.length?`<div class="tablewrap"><table><thead><tr><th>학생</th><th>상품</th><th>거래</th><th>수량</th><th>선택 이유</th><th>참고 기사</th></tr></thead><tbody>${S.all_orders.map(o=>{let ids=[];try{ids=JSON.parse(o.evidence_ids||'[]')}catch{}return `<tr><td>${esc(o.name)}</td><td>${esc(asset(o.asset)?.name||o.asset)}</td><td>${o.side==='buy'?'매수':'매도'}</td><td>${o.qty}주<br><span class="sub">수수료 ${money(o.fee||0)}</span></td><td style="white-space:normal;min-width:180px;max-width:350px;line-height:1.8">${esc(o.reason)}</td><td>${ids.length?ids.map(id=>`<button class="text-btn" onclick="openArticle(${id})">기사 #${id} ↗</button>`).join(''):'—'}</td></tr>`}).join('')}</tbody></table></div>`:emptyState('학생이 거래하면 선택 이유와 참고 기사를 함께 볼 수 있어요.')}</div>`}
async function adminAction(op){
 if(adminBusy)return;const pending=(S.participants||[]).filter(p=>!p.day_ready).length,day=S.room.day,phase=S.room.phase;
 const message=op==='close'?`${pending?`아직 ${pending}명이 선택 중입니다.\n`:''}${day}일차 거래를 마감하고 토론을 위해 멈출까요?`:`${pending&&phase==='trading'?`아직 ${pending}명이 선택 중입니다.\n`:''}${day===24?'24일차를 마치고 최종 결산할까요?':`${phase==='trading'?`${day}일차를 마치고 `:''}${day+1}일차를 열까요?`}${day<24&&[6,12,18,24].includes(day+1)?'\n다음 날에는 분기 실적과 새 가격이 공개됩니다.':''}`;
 if(!confirm(message+(day===24&&op!=='close'?'\n모든 보유 상품을 마지막 시세로 자동 매도하고 수수료와 이자를 정산합니다.':'')))return;adminBusy=true;document.querySelectorAll('[data-admin-action]').forEach(el=>el.disabled=true);
 try{const r=await api('/admin/'+(op==='close'?'close':'advance'),{method:'POST',...(op==='close'?{}:{body:{expected_day:day,expected_phase:phase}})});await refresh();toast(op==='close'?'거래를 마감했어요. 토론 후 다음 날을 열 수 있어요.':r.phase==='finished'?'최종 결산을 마쳤어요.':`${r.day}일차를 열었어요.`)}catch(e){await refresh();toast(e.message)}finally{adminBusy=false;document.querySelectorAll('[data-admin-action]').forEach(el=>el.disabled=false)}
}
function depositProducts(){return S.deposit_policy?.products||[{term:6,rate:.02},{term:12,rate:.045},{term:18,rate:.07},{term:24,rate:.1}]}
function depositRate(term){return depositProducts().find(p=>p.term===+term)?.rate||0}
function depositRules(){return `<p class="hint deposit-rules">최소 10,000원 · 10,000원 단위 · 거래 수수료 없음. 만기 수익률은 가입한 기간 전체의 이자예요. 중도해지 이자 = 원금 × 가입 때 만기 수익률 × 경과일 ÷ 약정일 × 50%. 가입 당일 해지는 이자가 없어요.</p>`}
function bank(){
 const products=depositProducts();
 if(isTeacherMarket())return marketCategories()+`<section class="card"><h2>정기예금 상품</h2><p class="sub">길게 맡길수록 같은 기간 대비 금리도 높아져요. 가입은 학생 계정에서 할 수 있어요.</p><div class="deposit-catalog">${products.map(({term,rate})=>`<article><h3>${term}일 예금</h3><b>만기 수익률 ${(rate*100).toFixed(1)}%</b><p>10,000원 가입 시 ${money(Math.round(10000*(1+rate)))} 수령</p><span class="tag">${S.room.day+term-1<=24?`오늘 가입하면 ${S.room.day+term-1}일차 만기`:'지금은 게임 종료 전 만기를 채울 수 없어요.'}</span></article>`).join('')}</div>${depositRules()}<p class="hint">기존 가입 건은 당시 약정 금리를 유지해요.</p></section>`;
 const deposits=S.deposits||[],active=deposits.filter(d=>d.status==='active');
 const available=products.filter(p=>S.room.day+p.term-1<=24),readOnly=S.role!=='player'||S.demo||S.room.phase!=='trading';
 return marketCategories()+`<div class="cols3">${metric('입출금 계좌',money(S.player.cash),'현재 사용 가능한 현금')}${metric('가입 중인 예금',active.length+'건',money(active.reduce((sum,d)=>sum+d.principal,0))+' 예치')}${metric('24일 예금 만기 수익률','10%','기간별 금리는 아래에서 비교해요.')}</div><div class="divider"></div><div class="grid"><section class="card"><h2>정기예금 가입</h2><p class="sub">길게 맡길수록 같은 기간 대비 금리도 높아져요.</p><label for="term">예금 기간 · 만기 수익률</label><select class="input" id="term" onchange="bankCalc()" ${!available.length?'disabled':''}>${products.map(({term,rate})=>`<option value="${term}" ${S.room.day+term-1>24?'disabled':''} ${term===available[0]?.term?'selected':''}>${term}일 예금 · ${(rate*100).toFixed(1)}%${S.room.day+term-1>24?' · 가입 종료':''}</option>`).join('')}</select><label for="principal">예금 원금 · 1만 원 단위</label><div class="deposit-amount"><input class="input" type="number" id="principal" value="10000" min="10000" max="100000000" step="10000" inputmode="numeric" aria-describedby="deposit-amount-hint" oninput="bankCalc()"><span>원</span></div><p class="hint" id="deposit-amount-hint" aria-live="polite">10,000원, 20,000원처럼 입력해 주세요.</p><div class="news"><div class="flex"><span>만기일</span><b id="maturity"></b></div><div class="flex jump"><span>만기 이자</span><b id="deposit-interest"></b></div><div class="flex jump"><span>만기 수령액</span><b id="receive"></b></div></div><button class="btn dark" id="deposit-submit" onclick="openDeposit()" ${readOnly||!available.length?'disabled':''}>정기예금 가입하기</button>${!available.length?'<p class="notice">게임 종료 전 만기를 채울 수 있는 예금이 없어요.</p>':''}${depositRules()}<p class="hint">가상의 24일을 1년으로 계산한 게임 금리예요.</p></section><section class="card"><h2>내 예금 통장</h2>${deposits.map(d=>`<div class="rowitem"><div class="flex"><b>${d.term}일 정기예금</b><span class="tag">${d.status==='active'?'진행 중':d.status==='matured'?'만기 완료':d.status==='settled'?'종료 정산':'중도해지'}</span></div><p class="hint">가입 ${d.start_day}일차 · 만기 ${d.start_day+d.term-1}일차 · 가입 때 약정 ${(d.rate*100).toFixed(2)}%</p><div class="flex"><b>${money(d.principal)}</b>${d.status==='active'?`<span>만기 ${money(d.maturity_paid??Math.round(d.principal*(1+d.rate)))}</span>`:`<span>수령 ${money(d.paid)}</span>`}</div>${d.status==='active'&&d.early_paid!==undefined?`<p class="hint early-deposit-quote">오늘 중도해지하면 ${money(d.early_paid)} 수령 · 이자 ${money(d.early_interest)}</p>`:''}${d.status==='active'?`<button class="btn secondary sm" onclick="closeDeposit(${d.id})" ${readOnly?'disabled':''}>중도 해지</button>`:''}</div>`).join('')||emptyState('가입한 예금이 없어요.')}</section></div>`;
}
function bankCalc(){
 if(!$('#principal'))return;
 const term=+$('#term').value,principal=+$('#principal').value,cash=myData().player?.cash||0;
 const valid=Number.isInteger(principal)&&principal>=10000&&principal<=100000000&&principal%10000===0,eligible=depositProducts().some(p=>p.term===term)&&S.room.day+term-1<=24;
 $('#deposit-amount-hint').textContent=valid?'최소 10,000원 · 10,000원 단위':'10,000원 이상을 10,000원 단위로 입력해 주세요.';
 $('#principal').setAttribute('aria-invalid',String(!valid));
 $('#maturity').textContent=eligible?(S.room.day+term-1)+'일차':'가입 종료';
 const interest=Math.round(principal*depositRate(term));
 $('#deposit-interest').textContent=valid&&eligible?money(interest):'—';$('#receive').textContent=valid&&eligible?money(principal+interest):'—';
 $('#deposit-submit').disabled=!valid||!eligible||principal>cash||S.role!=='player'||S.demo||S.room.phase!=='trading';
 if(valid&&principal>cash)$('#deposit-amount-hint').textContent='사용 가능한 현금이 부족해요.';
}
async function openDeposit(){
 const term=+$('#term').value,principal=+$('#principal').value;
 if(!Number.isInteger(principal)||principal<10000||principal%10000!==0||principal>100000000)return toast('예금은 최소 10,000원, 10,000원 단위로 가입해 주세요.');
 if(S.room.day+term-1>24)return toast('게임 종료 전에 만기가 오는 예금을 골라 주세요.');
 if(principal>S.player.cash)return toast('사용 가능한 현금이 부족해요.');
 if(!confirm(`${money(principal)}을 ${term}일 동안 예금할까요?\n만기 수익률 ${(depositRate(term)*100).toFixed(1)}% · 예상 수령 ${money(principal+Math.round(principal*depositRate(term)))}`))return;
 try{const r=await api('/deposits',{method:'POST',body:{term,principal}});await refresh();toast('예금에 가입했어요.'+(r.selection_resumed?' 오늘 상태는 선택 중으로 바뀌었어요.':''))}catch(e){toast(e.message)}
}
async function closeDeposit(id){
 const d=(S.deposits||[]).find(d=>d.id===id);if(!d)return;
 if(!confirm(`중도해지할까요?${d.early_paid!==undefined?`\n오늘 수령 ${money(d.early_paid)} · 이자 ${money(d.early_interest)}`:''}\n경과 기간에 해당하는 약정 이자의 50%만 지급돼요. 가입 당일은 이자가 없어요.`))return;
 try{const r=await api('/deposits/'+id+'/close',{method:'POST'});await refresh();toast('해지 완료: '+money(r.paid)+(r.selection_resumed?' · 오늘 상태는 선택 중으로 바뀌었어요.':''))}catch(e){toast(e.message)}
}

function unitMoney(value){return Number(value||0).toLocaleString('ko-KR',{maximumFractionDigits:2})+'원'}
function holdingAverage(h){return h.average_cost??(h.qty?h.cost/h.qty:0)}
function isTeacherMarket(){return S?.role==='admin'&&!isPreview()}
function bondTerms(a,qty=1){
 if(a.type!=='bond')return '';
 const p=S.bond_policy||{interval_days:3,year_days:24,next_payment_day:S.room.phase==='finished'?null:Math.ceil(S.room.day/3)*3},finished=S.room.phase==='finished';
 if(p.mode==='legacy_annual')return '<div class="bond-terms"><b>이전 지급방식으로 결산한 게임입니다.</b><p>이 게임의 채권 이자는 기존 연말 지급 내역을 유지합니다. 새 게임부터 3일 간격 지급을 적용해요.</p></div>';
 const coupon=Math.round(a.initial*a.yield*qty*p.interval_days/p.year_days);
 return `<div class="bond-terms"><b>채권 이자 · ${p.interval_days}일마다 지급</b><div><span>연이자율 · 24일 기준</span><strong>${pct(a.yield*100).replace('+','')}</strong></div><div><span>${qty}주를 ${p.interval_days}일 보유하면</span><strong>${money(coupon)}</strong></div><div><span>${finished?'지급 완료':'다음 지급일'}</span><strong>${finished?'24일차 마감':p.next_payment_day+'일차 마감'}</strong></div><p>액면 ${money(a.initial)} 기준 단리예요. 매일 마감 시 보유 수량만큼 쌓이고, 중간 매수·매도는 보유한 날만 계산해요. 팔기 전에 쌓인 이자도 지급일에 받아요. 이미 쌓인 이자는 당시 이율로 유지돼요. 가격 손익은 별도이며, 원 미만 금액은 모아 반올림해요.</p></div>`;
}
function bondIncomePanel(){
 const income=S.bond_income||{unpaid:0,paid:0},p=S.bond_policy||{next_payment_day:Math.ceil(S.room.day/3)*3};
 if(p.mode==='legacy_annual'||(!income.unpaid&&!income.paid&&!(S.holdings||[]).some(h=>asset(h.asset)?.type==='bond')))return '';
 return `<div class="notice bond-income-summary"><b>받을 채권 이자 ${money(income.unpaid)}</b><span> · ${p.next_payment_day?'다음 지급 '+p.next_payment_day+'일차 마감':'24일차까지 지급 완료'}</span><p class="hint no-margin">마감한 날까지 쌓인 이자로 총자산에 포함돼요. 지금까지 받은 채권 이자는 ${money(income.paid)}이며 현금과 입출금 내역에 반영됐어요.</p></div>`;
}
function teacherMarketPanel(a){return `<aside class="card teacher-market-panel"><h2>가격·거래 기준</h2><div class="trade-costs"><div><span>${S.room.day}일차 현재 거래가</span><b>${money(a.price)}</b></div><div><span>매수·매도 수수료</span><b>${feeRateLabel()}</b></div></div><p class="sub">학생 주문은 이 현재가로 즉시 체결됩니다. 하루 동안 가격은 같고, 다음 날 시작 시 갱신됩니다.</p>${bondTerms(a)}<div class="notice">교사용 시장 보기입니다. 학생별 보유 상품과 평균매수가는 학생 현황에서 확인할 수 있어요.</div><button class="btn secondary" onclick="go('players')">학생 현황 보기 ${icon('arrow')}</button></aside>`}
function feeRateLabel(){return String(S?.fee_policy?.percent??0.015)+'%'}
function quoteFee(gross){if(!(gross>0))return 0;const p=S?.fee_policy||{numerator:15,denominator:100000,minimum:1};return Math.max(p.minimum,Math.floor((gross*p.numerator+p.denominator/2)/p.denominator))}
function updateOrderTotal(){const a=asset(selected),qty=Number($('#qty')?.value),gross=Number.isInteger(qty)&&qty>0?a.price*qty:0,fee=quoteFee(gross);if($('#orderGross'))$('#orderGross').textContent=money(gross);if($('#orderFee'))$('#orderFee').textContent=money(fee);if($('#settlementLabel'))$('#settlementLabel').textContent=currentSide==='buy'?'총 결제액':'받을 금액';if($('#orderTotal'))$('#orderTotal').textContent=money(gross+(currentSide==='buy'?fee:-fee))}
function navGroup(k,teacher=false){
 if(teacher)return ['players','orders','preview'].includes(k)?'players':k==='admin'?'admin':['market','detail','bank','news','earnings'].includes(k)?'market':'home';
 return ['home','news','earnings'].includes(k)?'home':['market','detail','bank'].includes(k)?'market':['journal','orders'].includes(k)?'journal':'portfolio';
}
function goTeacher(k){if(S?.role!=='admin')return;closeModal();tab=k;if(k==='market'){marketFilter='all';marketSector='전체';marketSearch='';}render();window.scrollTo(0,0)}
function sectionTabs(preview=false){
 if(isPreview()&&!preview)return '';const k=currentView(),teacher=S.role==='admin'&&!isPreview();let entries=[];
 if(teacher&&['players','orders'].includes(k))entries=[['players','학생별 현황'],['orders','거래와 근거']];
 else if(teacher&&['market','bank','news','earnings'].includes(k))entries=[['market','투자 상품'],['news','뉴스'],['earnings','분기 실적']];
 else if(['home','news','earnings'].includes(k)&&(!teacher||k!=='home'))entries=teacher?[['home','수업 진행'],['news','뉴스'],['earnings','분기 실적'],['market','상품 살펴보기']]:[['home','오늘의 핵심'],['news','뉴스 모아보기'],['earnings','분기 실적']];
 else if(!teacher&&['journal','orders'].includes(k))entries=[['journal','판단·돌아보기'],['orders','입출금 내역']];
 return entries.length?`<nav class="section-tabs" aria-label="${teacher?'교사 자료':'관련 화면'}">${entries.map(([id,label])=>`<button class="${id===k?'active':''}" aria-current="${id===k?'page':'false'}" onclick="go('${id}')">${label}${id==='earnings'&&(S.calendar||[]).some(q=>q.released&&q.day===S.room.day)?'<span class="nav-badge">새 발표</span>':''}</button>`).join('')}</nav>`:'';
}
function marketCategories(){return `<nav class="section-tabs asset-categories" aria-label="투자 상품 종류">${[['all','전체'],['stock','주식'],['etf','ETF'],['deposit','예금'],['bond','채권'],['gold','금']].map(([k,v])=>`<button class="${k==='deposit'?currentView()==='bank'?'active':'':currentView()!=='bank'&&marketFilter===k?'active':''}" onclick="${k==='deposit'?"go('bank')":`marketFilter='${k}';marketSector='전체';go('market')`}">${v}</button>`).join('')}</nav>`}
function filteredMarketAssets(){return S.assets.filter(a=>(marketFilter==='all'||(marketFilter==='watch'?(S.watchlist||[]).includes(a.id):a.type===marketFilter))&&(marketSector==='전체'||a.sector===marketSector)&&(!marketSearch||a.name.includes(marketSearch)||a.id.toLowerCase().includes(marketSearch.toLowerCase())))}
function resetNewsFilters(){newsSector='전체';newsHorizon='all';newsMode='all';newsFocus='';render()}
function parseEvidence(ids){try{return Array.isArray(ids)?ids:JSON.parse(ids||'[]')}catch{return []}}
function horizonOptions(selected){return ['다음 실적 발표까지','후속 뉴스가 나올 때','2~3일 뒤','게임 종료 시점'].map(v=>`<option ${v===selected?'selected':''}>${v}</option>`).join('')}
function openNoteComposer(id=null){if(id)journalAsset=id;noteComposerOpen=true;go('journal')}
async function reflectTrade(oid){try{const r=await api('/orders/'+oid+'/note',{method:'POST'});await refresh();reflectionModal(r.id)}catch(e){toast(e.message)}}
async function openStudentView(){tab='preview';if(previewPid){await loadPreview(previewPid)}else if(S.participants?.length){await loadPreview(S.participants[0].id)}else render();window.scrollTo(0,0)}
function analyzeArticle(nid,aid){if($('#trade-meta')?.dataset.asset===aid){const el=document.querySelector('#trade-evidence input[value="'+nid+'"]');if(el)el.checked=true}const d=tradeDrafts[aid]||{qty:1,reason:'',ids:[]};d.ids=[...new Set([...d.ids,nid])].slice(0,5);tradeDrafts[aid]=d;closeModal();detail(aid)}
function orders(){const labels={trade:'거래',fee:'수수료',deposit:'예금',interest:'이자',teacher:'교사 조정'};return `<section class="card"><h2>입출금 내역</h2><p class="sub">거래 이유와 돌아보기는 ‘판단·돌아보기’에 함께 모여 있어요.</p>${(S.ledger||[]).map(x=>`<div class="rowitem"><div class="flex"><div><b>${esc(x.note)}</b><div class="sub">${x.day}일차 · ${esc(labels[x.kind]||'기타')}</div></div><b class="${x.amount>=0?'green':'negative'}">${x.amount>0?'+':''}${money(x.amount)}</b></div></div>`).join('')||emptyState('아직 입출금 내역이 없어요.')}</section>`}
function adminPanel(){return progressionControls()+resetControls()+`<div class="card"><h2>운영 설정</h2><p class="sub">하루 진행과 뉴스 분위기는 ‘수업 진행’에서 조절해요.</p><details class="disclosure"><summary>직접 뉴스 추가하기</summary><p class="notice manual-news-timing">${S.room.phase==='closed'?'지금은 거래 마감 상태입니다. 지금 등록하면 학생이 오늘 매매로 대응할 시간이 없어요.':S.room.day===24?'24일차에는 다음 거래일이 없어 가격 영향이 적용되지 않아요.':'학생에게 기사를 읽고 판단할 시간을 준 뒤 다음 날을 열어 주세요.'}</p><p class="sub">등록 즉시 오늘 뉴스에 공개되며, 입력한 가격 영향은 다음 날 시작에 한 번 반영됩니다. 시장 등 다른 요인과 합산되므로 최종 등락률과는 다를 수 있어요. 자동 기업 뉴스와 달리 사업 실적을 바꾸지는 않습니다.</p><label for="nt">제목</label><input class="input" id="nt" maxlength="120"><label for="nb">내용</label><textarea class="input" id="nb" rows="3" maxlength="400"></textarea><div class="half"><div><label for="ns">영향 대상</label><select class="input" id="ns"><option value="전체">시장 전체</option>${[...new Set(S.assets.filter(a=>a.type==='stock').map(a=>a.sector))].map(k=>`<option>${k}</option>`).join('')}${S.assets.filter(a=>a.type==='stock').map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div><label for="ni">다음 날 가격 효과 (%p)</label><input class="input" id="ni" type="number" value="0" min="-12" max="12" step="0.5"></div></div><button class="btn secondary jump" onclick="addNews()">뉴스 발행</button></details><details class="disclosure"><summary>운영 기록 보기</summary>${(S.logs||[]).map(l=>`<div class="rowitem"><span class="tag">${l.day}일차</span> <span>${esc(l.detail)}</span></div>`).join('')||emptyState('아직 운영 기록이 없어요.')}</details></div>`}


function resetControls(){
 const backup=S.reset_backup;
 return `<section class="card reset-controls"><div class="section-title"><div><h2>1일차부터 새 게임 시작</h2><p class="sub no-margin">현재 ${S.room.day}일차 · 학생 ${S.participants?.length||0}명</p></div><span class="tag">교사 전용</span></div><p>학생 계정과 방 코드를 유지하고, 날짜·자산·플레이 기록을 시작 상태로 되돌립니다.</p><button class="btn red" onclick="resetGameModal()">${icon('refresh')} 플레이 데이터 초기화</button>${backup?`<div class="reset-backup"><span class="sub">최근 초기화 전 기록: ${backup.from_day}일차</span><button class="text-btn" onclick="downloadResetBackup()">백업 내려받기 ${icon('arrow')}</button></div>`:'<p class="hint">초기화 직전 기록은 자동으로 백업되며, 여기서 내려받을 수 있어요.</p>'}</section>`;
}
function resetGameModal(){
 if(S?.role!=='admin')return;
 showModal(`<div class="modal-titlebar"><b>새 게임 시작</b><button class="modal-x" aria-label="닫기" onclick="closeModal()">${icon('close')}</button></div><h2>${S.room.day}일차를 마치고 1일차로 초기화할까요?</h2><div class="reset-summary"><div><b>유지되는 것</b><p>게임방 코드, 학생 이름·PIN, 교사 비밀번호, 시작 자금 설정</p></div><div><b>새로 시작하는 것</b><p>날짜, 현금, 보유 상품, 예금, 거래·수수료 내역, 뉴스·실적, 투자 기록과 관심 목록</p></div></div><p class="notice">모든 학생의 현금이 시작 자금 ${money(S.room.start_cash)}으로 돌아갑니다. 현재 기록은 먼저 백업하고, 새로운 뉴스로 1일차를 시작합니다.</p><form onsubmit="event.preventDefault();submitGameReset()"><label for="reset-confirm">확인하려면 ‘초기화’를 입력하세요.</label><input class="input" id="reset-confirm" autocomplete="off" placeholder="초기화" oninput="document.getElementById('reset-submit').disabled=this.value!=='초기화'" required><div class="modal-actions"><button type="button" class="btn ghost" onclick="closeModal()">취소</button><button type="submit" class="btn red" id="reset-submit" disabled>백업하고 1일차 시작</button></div></form>`,'새 게임 초기화 확인');
}
async function submitGameReset(){
 if(S?.role!=='admin'||$('#reset-confirm')?.value!=='초기화')return;
 const button=$('#reset-submit');if(button?.disabled)return;button.disabled=true;
 try{await api('/admin/reset',{method:'POST',body:{confirmation:'초기화',expected_day:S.room.day,expected_generation:S.room.generation||0}});closeModal();await refresh();window.scrollTo(0,0);toast('학생 계정은 유지하고, 시작 자금으로 1일차를 열었어요.')}catch(e){await refresh();if(button.isConnected)button.disabled=false;toast(e.message)}
}
async function downloadResetBackup(){
 try{const data=await api('/admin/reset-backup'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`haru-before-reset-day-${data.room.day}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}
}
function clearGameDrafts(){
 closeModal();$('#trade-meta')?.remove();$('#note-thesis')?.remove();
 tradeDrafts={};noteDraft={thesis:'',risk:'',horizon:'다음 실적 발표까지',ids:[]};evidenceDraft=null;noteComposerOpen=false;
 history=[];pickedDay=null;previewData=null;previewPid=null;previewTab='home';earningsQ=null;earningsAsset='HBEL';journalAsset='HBEL';
 newsFocus='';newsScope='today';newsSector='전체';newsHorizon='all';newsMode='all';newsAdvanced=false;marketFilter='all';marketSearch='';marketSector='전체';tab='home';
}
async function refresh(quiet=false){
 if(S?.demo){render();return}if(refreshing)return;refreshing=true;
 try{let next=await api('/state');let finishedNow=S&&S.room.phase!=='finished'&&next.room.phase==='finished';let gameChanged=S&&(next.room.generation||0)!==(S.room.generation||0),dayChanged=S&&next.room.day!==S.room.day;if(gameChanged)clearGameDrafts();if(dayChanged||gameChanged)closeModal();S=next;if(finishedNow){tab='home';previewTab='home';closeModal();}if((dayChanged||gameChanged||finishedNow)&&S.role==='player'&&!S.demo)showDayTransition(S.room,gameChanged);syncClassClock(next.progression);if(S.role==='admin'&&tab==='preview'&&previewPid)previewData=await api('/admin/student/'+previewPid);if(currentView()==='detail'&&(dayChanged||!history.length))history=await api('/history/'+selected);render();if(gameChanged)toast('선생님이 새 게임을 열었어요. 1일차부터 다시 시작합니다.');else if(dayChanged)toast(`${S.room.day}일차가 시작됐어요.${[6,12,18,24].includes(S.room.day)?' 분기 실적이 공개되었습니다.':''}`)}
 catch(e){if(e.message.includes('로그인')){token='';localStorage.removeItem('haru_token');S=null;render()}else if(!quiet)toast(e.message)}finally{refreshing=false}
}
function render(){
 if(!S){$('#app').innerHTML=authView();return}
 if($('#qty')&&$('#trade-meta'))tradeDrafts[$('#trade-meta').dataset.asset]={qty:$('#qty').value,reason:$('#reason').value,ids:pickedEvidence('trade-evidence')};
 if($('#note-thesis')){noteDraft.thesis=$('#note-thesis').value;noteDraft.risk=$('#note-risk')?.value||'';noteDraft.horizon=$('#note-horizon')?.value||noteDraft.horizon;noteDraft.ids=pickedEvidence('note-evidence')}
 $('#app').innerHTML=head();let view=S.role==='admin'?({home:teacherHome,preview:adminPreview,players:participants,news,earnings,market,bank,detail:detailView,orders:adminOrders,admin:adminPanel}[tab]||teacherHome):({home:playerHome,market,detail:detailView,bank,portfolio,news,orders,earnings,journal}[tab]||playerHome);
 $('#page').innerHTML=(S.room.phase==='finished'&&S.finale&&tab==='home'?'':sectionTabs()+breakingBanner())+view();if(currentView()==='detail'&&tradeDrafts[selected]&&$('#qty')){let d=tradeDrafts[selected];$('#qty').value=d.qty;$('#reason').value=d.reason;document.querySelectorAll('#trade-evidence input').forEach(el=>el.checked=d.ids.includes(+el.value));updateOrderTotal()}if(currentView()==='journal'&&$('#note-horizon')){$('#note-horizon').value=noteDraft.horizon;document.querySelectorAll('#note-evidence input').forEach(el=>el.checked=(noteDraft.ids||[]).includes(+el.value)||+el.value===evidenceDraft)}if(currentView()==='bank'&&(S.role==='player'||(isPreview()&&previewData)))bankCalc();if(S.role==='admin'&&tab==='home'&&S.room.phase!=='finished')loadShare();updateClassClock();
}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const all=[...$('#modal-root .modal').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
if(token){$('#app').innerHTML='<div class="loading"><div><div class="pulse"></div>투자 연구소에 연결하고 있어요.</div></div>';refresh()}else render();
setInterval(()=>{if(!token||!S||S.demo||document.visibilityState!=='visible'||$('#modal-root')?.children.length)return;let el=document.activeElement;if(el&&['INPUT','SELECT','TEXTAREA'].includes(el.tagName))return;refresh(true)},12000);

setInterval(()=>{updateClassClock();pollProgression()},1000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')pollProgression()});
